insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 5, 'സുബ്ഹ്ന്റെ സുന്നത്ത് നിസ്കരിക്കാതെ ഇമാമിനെ തുടർന്നാൽ', 'بَابٌ: إِذَا أَدْرَكَ الْإِمَامَ وَلَمْ يُصَلِ رَكْعَتَيِ الْفَجْرِ', 529 from books where volume_id=1 and book_no=21 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
