insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 7, 'ഫജ്റിന്റെ രണ്ട് റക്അത്തിന്റെ സമയം', 'بَابٌ: وَقْتُ رَكْعَتَيِ الْفَجْرِ', 530 from books where volume_id=1 and book_no=21 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 8, 'സുബ്ഹിയുടെ രണ്ട് റക്അത്ത് ലഘുവാക്കൽ, നബി(സ) അതിൽ', 'بَابٌ: مَا جَاءَ فِي تَخْفِيفِ رَكْعَتَيِ الْفَجْرِ وَمَا كَانَ النَّبِيُّ (صلعم) يَقْرَأُ فِيهِمَا', 530 from books where volume_id=1 and book_no=21 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 9, 'ഫജ്റിന്റെ രണ്ട് റക്അത്തിനു ശേഷമുള്ള സംസാരം', 'بَابٌ: الْكَلَامُ بَعْدَ رَكْعَتَيِ الْفَجْرِ', 532 from books where volume_id=1 and book_no=21 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 10, 'ഇഖാമത്ത് വിളിച്ചാൽ ഫർള് ഒഴികെ മറ്റൊരു നിസ്കാരവുമില്ല', 'بَابٌ: إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةَ', 532 from books where volume_id=1 and book_no=21 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
