insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 12, 'ഫജ്ർ വെളിവായ ശേഷം രണ്ട് റക്അത്തൊഴികെ മറ്റു നിസ്കാരമില്ല', 'بَابٌ: مَا جَاءَ "لَا صَلَاةَ بَعْدَ طُلُوعِ الْفَجْرِ إِلَّا رَكْعَتَيْنِ"', 533 from books where volume_id=1 and book_no=21 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 13, 'ദിനേന ഫർളുകൾ ഒഴികെ പന്ത്രണ്ട് റക്അത്ത് നിസ്കരിച്ചാലുള്ള പ്രതിഫലം', 'بَابُ: ثَوَابُ مَنْ صَلَّي فِي الْيَوْمِ وَاللَّيْلَةِ ثنْتَيْ عَشْرَةَ رَكْعَةً سَوِي الْمَكْتُوبَةِ', 533 from books where volume_id=1 and book_no=21 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
