insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الاِسْتِخَارَةَ فِي الأُمُورِ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: "إِذَا هَمَّ أَحَدُكُمْ بِالأَمْرِ، فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لِيَقُلْ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي، فِي دِينِي وَمَعِيشَتِي وَعَاقِبَةِ أَمْرِي، أَوْ قَالَ: عَاجِلِ أَمْرِي وَآجِلِه، فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيه، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي، فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، أَوْ قَالَ: فِي عَاجِلِ أَمْرِي وَآجِلِه، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِه، قَالَ: وَيُسَمِّي حَاجَتَهُ". (خ,د,ت,ن,جه)', 'ജാബിറിബ്നു അബ്ദില്ല(റ): ഖുർആനിലെ ഒരു സൂറത്ത് പഠിപ്പിക്കുംപോലെ കാര്യങ്ങളിൽ ഇസ്തിഖാറ (നന്മ തേടുക) ചെയ്യാൻ നബി(സ) ഞങ്ങളെ പഠിപ്പിക്കാറുണ്ടായിരുന്നു; അവിടുന്ന് പറയും: "നിങ്ങളിൽ ആരെങ്കിലും വല്ല കാര്യവും ഉദ്ദേശിച്ചാൽ ഫർദല്ലാത്ത രണ്ട് റക്അത്ത് നിസ്കരിക്കുക. എന്നിട്ട് ഇപ്രകാരം പറയുക: അല്ലാഹുവേ, നിന്റെ ജ്ഞാനം കൊണ്ട് ഞാൻ നന്മ തേടുന്നു. നിന്റെ കഴിവ് കൊണ്ട് കഴിവിനെ തേടുന്നു. നിന്റെ മഹത്തായ ഔദാര്യത്തിൽ നിന്ന് ഞാൻ ചോദിക്കുന്നു. നിനക്ക് എല്ലാം സാധിക്കുന്നു. എനിക്ക് സാധിക്കുകയില്ല. നീ അറിയുന്നു. ഞാൻ അറിയുന്നില്ല. നീ ഗോപ്യമായതൊക്കെയും അറിയുന്നവനല്ലോ. അല്ലാഹുവേ! ഈകാര്യം എന്റെ ദീനിലും ജീവിതത്തിലും എന്റെ കാര്യത്തിന്റെ അന്ത്യത്തിലും (അല്ലെങ്കിൽ എന്റെ കാര്യത്തിന്റെ തുടക്കത്തിലും അന്ത്യത്തിലും എന്നാണ് നബി(സ) പറഞ്ഞത്) എനിക്ക് ഗുണകരമാണ് എന്നാണ് നീ അറിയുന്നതെങ്കിൽ എനിക്ക് അതിന് കഴിവ് നൽകുകയും അത് എനിക്ക് എളുപ്പമാക്കിത്തരികയും അതിൽ എനിക്ക് അനുഗ്രഹം നൽകുകയും ചെയ്യേണമേ! ഈ കാര്യം എന്റെ മതത്തിലും എന്റെ ജീവിതത്തിലും എന്റെ കാര്യത്തിന്റെ അന്ത്യത്തിലും (അല്ലെങ്കിൽ എന്റെ കാര്യത്തിന്റെ തുടക്കത്തിലും അന്ത്യത്തിലും എന്നാണ് നബി(സ) പറഞ്ഞത്) തിന്മയാണെന്നാണ് നീ അറിയുന്നതെങ്കിൽ ഇതിനെ എന്നിൽ നിന്നും എന്നെ ഇതിൽ നിന്നും തിരിച്ചു കളയേണമേ! നന്മ ചെയ്യുവാൻ എനിക്ക് കഴിവ് നൽകണേ. അത് എവിടെ ആയാലും. പിന്നെ അതുകൊണ്ട് എന്നെ തൃപ്തിപ്പെടുത്തുകയും ചെയ്യേണമേ എന്ന് ചൊല്ലട്ടെ." നബി(സ) പറഞ്ഞു: "അവൻ (പ്രാർത്ഥനയിൽ) തന്റെ ആവശ്യം വ്യക്തമാക്കണം." (ബു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറിബ്നു അബ്ദില്ല(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَاصِمِ بْنِ ضَمْرَةَ السَّلُولِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْنَا عَلِيًّا – رَضِيَ اللهُ عَنْهُ – عَنْ تَطَوُّعِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالنَّهَارِ؟ فَقَالَ :إِنَّكُمْ لَا تُطِيقُونَهُ. فَقُلْنَا: أَخْبِرْنَا بِهِ، نَأْخُذْ مِنْهُ مَا اسْتَطَعْنَا. قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى الْفَجْرَ يُمْهِلُ، حَتَّى إِذَا كَانَتِ الشَّمْسُ مِنْ هَا هُنَا – يَعْنِي مِنْ قِبَلِ الْمَشْرِقِ – بِمِقْدَارِهَا مِنْ صَلَاةِ الْعَصْرِ مِنْ هَا هُنَا – يَعْنِي مِنْ قِبَلِ الْمَغْرِبِ – قَامَ فَصَلَّى رَكْعَتَيْنِ. ثُمَّ يُمْهِلُ حَتَّى إِذَا كَانَتِ الشَّمْسُ مِنْ هَا هُنَا – يَعْنِي مِنْ قِبَلِ الْمَشْرِقِ – مِقْدَارِهَا مِنْ صَلَاةِ الظُّهْرِ مِنْ هَا هُنَا، قَامَ فَصَلَّى أَرْبَعًا. وَأَرْبَعًا قَبْلَ الظُّهْرِ إِذَا زَالَتِ الشَّمْسُ، وَرَكْعَتَيْنِ بَعْدَهَا. وَأَرْبَعًا قَبْلَ الْعَصْرِ، يَفْصِلُ بَيْنَ كُلِّ رَكْعَتَيْنِ بِالتَّسْلِيمِ عَلَى الْمَلَائِكَةِ الْمُقَرَّبِينَ وَالنَّبِيِّينَ، وَمَنْ تَبِعَهُمْ مِنَ الْمُسْلِمِينَ وَالْمُؤْمِنِينَ. قَالَ عَلِيٌّ: فَتِلْكَ سِتَّ عَشْرَةَ رَكْعَةً، تَطَوُّعُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالنَّهَارِ، وَقَلَّ مَنْ يُدَاوِمُ عَلَيْهَا. قَالَ وَكِيعٌ: زَادَ فِيهِ أَبِي: فَقَالَ حَبِيبُ بْنُ أَبِي ثَابِتٍ: يَا أَبَا إِسْحَقَ، مَا أُحِبُّ أَنَّ لِي بِحَدِيثِكَ هَذَا مِلْءَ مَسْجِدِكَ هَذَا ذَهَبًا. (ت,ن,جه)', 'ആസിമുബ്നു ളംറ(റ): പകലിൽ നബി(സ)നിർവ്വഹിച്ചിരുന്ന സുന്നത്ത് നിസ്കാരങ്ങളെക്കുറിച്ച് ഞങ്ങൾ അലി(റ)യോട് ചോദിച്ചു. അലി(റ) പറഞ്ഞു: നിങ്ങൾക്കതിന് കഴിയില്ല. ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾക്ക് പറഞ്ഞുതരൂ. ഞങ്ങൾക്ക് കഴിയുന്ന അത്രയും നിർവ്വഹിക്കാമല്ലോ. അലി(റ) പറഞ്ഞു: നബി(സ) സുബ്ഹി നിസ്കാരം കഴിഞ്ഞാൽ (ഏതാനും സമയം) സാവകാശം ചെയ്യും. അങ്ങനെ അസ്റിന്റെ സമയം മുതൽ മഗ്രിബിന്റെ സമയം വരെ സൂര്യൻ സഞ്ചരിച്ചെത്തുന്ന അത്രയും ദൂരത്തോളം, കിഴക്കു ഭാഗത്തുനിന്ന് സൂര്യൻ സഞ്ചരിച്ചെത്തിയാൽ രണ്ട് റക്അത്ത് നിസ്കരിക്കും. സൂര്യൻ കിഴക്കുനിന്നും ളുഹ്റിന്റെ സമയമാകുന്നതുവരെ സഞ്ചരിച്ചെത്തിയാൽ നാല് റക്അത്ത് നിസ്കരിക്കും. സൂര്യൻ മധ്യത്തിൽ നിന്ന് നീങ്ങിയാൽ ളുഹ്ർ നിസ്കരിക്കുന്നതിനു മുമ്പ് നാല് റക്അത്ത് നിസ്കരിക്കും. ളുഹ്റിനുശേഷം രണ്ടു റക്അത്ത്. അസ്റിനു മുമ്പ് നാല് റക്അത്ത്. എല്ലാ ഈരണ്ട് റക്അത്തുകൾക്കിടയിലും മലക്കുകളുടെയും നബിമാരുടെയും അവരെ പിൻപറ്റിയ വിശ്വാസികളുടെയും മേൽ സലാം ചൊല്ലി കൊണ്ട് അവയെ വേർതിരിക്കും. അലി(റ) തുടരുന്നു: അങ്ങനെ പതിനാറ് റക്അത്താണ് നബി(സ) പകലിൽ സുന്നത്തായി നിർവ്വഹിച്ചിരുന്നത്. അത് നിത്യമായി ചെയ്യുന്നവർ വളരെ വിരളമത്രെ. വകീഅ് പറയുന്നു: ഈ ഹദീസിന്റെ കൂടെ എന്റെ പിതാവ് ഇങ്ങനെ അധികം പറഞ്ഞിട്ടുണ്ട്: ഹബീബ്നു സാബിത്ത് പറഞ്ഞു: ഓ അബൂഇസ്ഹാഖ്! നീ പറഞ്ഞുതന്ന ഈ ഹദീസിന് പകരമായി ഈ പള്ളി നിറയെ സ്വർണ്ണം കിട്ടാൻ ഞാൻ ഇഷ്ടപ്പെടുന്നില്ല. (തു,ന,ജ)', 'عَاصِمِ بْنِ ضَمْرَةَ السَّلُولِيِّ', 'ആസിമുബ്നു ളംറ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 522, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيَعْجِزُ أَحَدُكُمْ إِذَا صَلَّى: أَنْ يَتَقَدَّمَ أَوْ يَتَأَخَّرَ، أَوْ عَنْ يَمِينه، أَوْ عَنْ شَمَاله" يَعْنِي السُّبْحَةَ. (خ,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്കരിച്ചു കഴിഞ്ഞാൽ മുന്നിലേക്കോ പിന്നിലേക്കോ വലത് ഭാഗത്തേക്കോ ഇടതുഭാഗത്തേക്കോ അൽപം മാറിനിൽക്കാൻ ആർക്കെങ്കിലും പ്രയാസമുണ്ടോ?" സുന്നത്ത് നിസ്കരിക്കാൻ വേണ്ടി മാറിനിൽക്കുന്നതിനെയാണ് നബി(സ) ഉദ്ദേശിച്ചത്. (ബു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 523, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُصَلِّي الْإِمَامُ فِي مُقَامِهِ الَّذِي صَلَّى فِيهِ الْمَكْتُوبَةَ حَتَّى يَتَنَحَّى عَنْهُ". (د,جه)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): നബി(സ) പറഞ്ഞു: "ഇമാം, ഫർദ് നിസ്കാരം നിർവ്വഹിച്ച സ്ഥലത്ത് (സുന്നത്ത്) നിസ്കരിക്കരുത്. അവിടെ നിന്നും അൽപം മാറി നിന്ന് നിസ്കരിക്കണം." (ദ,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 523, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَاصِمِ بْنِ عَمْرو رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ نَفَرٌ مِنْ أَهْلِ الْعِرَاقِ إِلَى عُمَرَ رَضِيَ اللهُ عَنْهُ، فَلَمَّا قَدِمُوا عَلَيْهِ قَالَ لَهُمْ: مِمَّنْ أَنْتُمْ؟ قَالُوا: مِنْ أَهْلِ الْعِرَاقِ. قَالَ: فَبِإِذْنٍ جِئْتُمْ؟ قَالُوا: نَعَمْ. قَالَ: فَسَأَلُوهُ عَنْ صَلَاةِ الرَّجُلِ فِي بَيْتِه؟ فَقَالَ عُمَرُ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَمَّا صَلَاةُ الرَّجُلِ فِي بَيْتِه فَنُورٌ، فَنَوِّرُوا بُيُوتَكُمْ". [في إسناده ضعيف] (جه)', 'ആസിമിബ്നു അംറ്(റ): ഇറാഖുകാരിൽപെട്ട ഒരു സംഘം ഉമറി(റ)ന്റെ അടുക്കൽ വന്നു. അവർ വന്നപ്പോൾ ഉമർ(റ) ചോദിച്ചു: നിങ്ങൾ എവിടെ നിന്നാണ്? അവർ പറഞ്ഞു: ഞങ്ങൾ ഇറാഖികളാണ്. ഉമർ(റ) വീണ്ടും ചോദിച്ചു: നിങ്ങൾ അനുമതിയോടു കൂടിയാണോ വന്നത്? അവർ പറഞ്ഞു: അതെ, അവർ അദ്ദേഹത്തോട് ഒരാൾ തന്റെ വീട്ടിൽ വെച്ച് (സുന്നത്ത്) നിസ്കരിക്കുന്നതിനെക്കുറിച്ച് ചോദിച്ചു. ഉമർ(റ) പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "തന്റെ ഭവനത്തിൽ വെച്ചുള്ള ഒരാളുടെ നിസ്കാരം അവന് പ്രകാശമാണ്. അതിനാൽ നിങ്ങൾ വീടുകളെ പ്രകാശിപ്പിക്കുക." [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നു മാജ പറയുന്നു] (ജ)', 'عَاصِمِ بْنِ عَمْرو', 'ആസിമിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده ضعيف', null, 523, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَضَى أَحَدُكُمْ صَلَاتَهُ فَلْيَجْعَلْ لِبَيْتِه مِنْهَا نَصِيبًا، فَإِنَّ اللهَ جَاعِلٌ فِي بَيْتِه مِنْ صَلَاتِه خَيْرًا". (م,جه)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): അബൂസഈദിൽ ഖുദ്രീ(റ)യിൽ നിന്നും: നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ നിസ്കാരം നിർവഹിച്ചു കഴിഞ്ഞാൽ തന്റെ വീടിന്നു വേണ്ടി അതിൽനിന്ന് ഒരു ഓഹരി നീക്കിവെക്കുക. കാരണം അല്ലാഹു അവന്റെ വീട്ടിൽ അവന്റെ നിസ്കാരത്തിൽ നിന്ന് അനുഗ്രഹത്തെ നൽകുന്നതാണ്." (മു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 523, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ زَيْدِ بْنِ ثَابِت رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَفْضَلُ صَلَاتِكُمْ فِي بُيُوتِكُمْ، إِلَّا الْمَكْتُوبَةَ". حَسَنٌ (ق,د,ت,ن)', 'സൈദുബ്നു സാബിത്ത്(റ): നബി(സ) പറഞ്ഞു: "ഫർദുകൾ ഒഴികെയുള്ള നിങ്ങളുടെ നിസ്കാരങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ടമായത് വീടുകളിൽ വെച്ചുള്ള നിസ്കാരങ്ങളാണ്." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു,ന)', 'زَيْدِ بْنِ ثَابِت', 'സൈദുബ്നു സാബിത്ത്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلُّوا فِي بُيُوتِكُمْ، وَلَا تَتَّخِذُوهَا قُبُورًا". حَسَنٌ صَحِيحٌ. (ق,د,ن,جه)', 'ഇബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ ഭവനങ്ങളിൽ നിസ്കരിക്കൂ. അവയെ നിങ്ങൾ ശ്മശാനങ്ങളാക്കരുത്." (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ اللهِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ :أَيُّمَا أَفْضَلُ، الصَّلَاةُ فِي بَيْتِي أَوِ الصَّلَاةُ فِي الْمَسْجِدِ؟ قَالَ: "أَلَا تَرَى إِلَى بَيْتِي؟ مَا أَقْرَبَهُ مِنَ الْمَسْجِدِ! فَلَأَنْ أُصَلِّيَ فِي بَيْتِي أَحَبُّ إِلَيَّ مِنْ أَنْ أُصَلِّيَ فِي الْمَسْجِدِ، إِلَّا أَنْ تَكُونَ صَلَاةً مَكْتُوبَةً". (جه)', 'അബ്ദുല്ലാഹിബ്നു സഅദ്(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: എന്റെ വീട്ടിൽ വെച്ചുള്ള നിസ്കാരമാണോ അതോ, പള്ളിയിൽ വെച്ചുള്ള നിസ്കാരമാണോ ഏറ്റവും ശ്രേഷ്ടമായത്? നബി(സ) പറഞ്ഞു: "നീ എന്റെ വീട്ടിലേക്ക് നോക്കുന്നില്ലേ? പള്ളിയുമായി അത് എത്ര അടുത്തിരിക്കുന്നു. വീട്ടിൽ വെച്ചുള്ള എന്റെ നിസ്കാരം പള്ളിയിലുള്ള നിസ്കാരത്തെക്കാൾ എനിക്ക് പ്രിങ്കരമാണ്, ഫർളുകൾ ഒഴികെ." (ജ)', 'عَبْدِ اللهِ بْنِ سَعْدٍ', 'അബ്ദുല്ലാഹിബ്നു സഅദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى الضُّحَى ثِنْتَيْ عَشْرَةَ رَكْعَةً بَنَى اللهُ لَهُ قَصْرًا مِنْ ذَهَبٍ فِي الْجَنَّةِ". (ت,جه)', 'അനസിബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "പന്ത്രണ്ട് റക്അത്ത് ളുഹാ നിസ്കരിക്കുന്ന വ്യക്തിക്ക് അല്ലാഹു സ്വർഗത്തിൽ ഒരു സ്വർണ്ണമാളിക നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്." (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസിബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ بَيْتَهَا يَوْمَ فَتْحِ مَكَّةَ، فَاغْتَسَلَ، فَسَبَّحَ ثَمَانَ رَكَعَات، مَا رَأَيْتُهُ صَلَّى صَلَاةً قَطُّ أَخَفَّ مِنْهَا، غَيْرَ أَنَّهُ كَانَ يُتِمُّ الرُّكُوعَ وَالسُّجُودَ. حَسَنٌ صَحِيحٌ (ق,ت)', 'ഉമ്മുഹാനിഅ്(റ): നബി(സ) മക്കാ വിജയ ദിവസം അവളുടെ വീട്ടിൽ ചെല്ലുകയും കുളിക്കുകയും എട്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്തു. ഇതിനേക്കാൾ ലഘുവായ മറ്റൊരു നിസ്കാരം ഞാൻ കണ്ടിട്ടില്ല. പക്ഷേ, നബി(സ) റുകൂഉം സുജൂദും പൂർത്തിയാക്കിയിരുന്നു. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,തു)', 'أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي الدَّرْدَاءِ وَ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُمَا: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَنِ اللهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ: ابْنَ آدَمَ، ارْكَعْ لِي مِنْ أَوَّلِ النَّهَارِ أَرْبَعَ رَكَعَاتٍ أَكْفِكَ آخِرَهُ". حَسَنٌ غَرِيبٌ (د,ت)', 'അബുദ്ദർദാഅ്, അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു മനുഷ്യ സന്തതിയോട് പറഞ്ഞു: പകലിന്റെ തുടക്കത്തിൽ നീ എനിക്ക് നാല് റക്അത്ത് നിസ്കരിക്കുക. എങ്കിൽ പകലിന്റെ അവസാനം വരെ ഞാൻ നിനക്ക് മതിയാക്കുന്നതാണ്." ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു. (ദ,തു)', 'أَبِي الدَّرْدَاءِ وَ أَبِي ذَرٍّ', 'അബുദ്ദർദാഅ്, അബൂദർറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 524, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَافَظَ عَلَى شُفْعَةِ الضُّحَى غُفِرَ لَهُ ذُنُوبُهُ، وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ". (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും രണ്ട് റക്അത്ത് ളുഹാ നിസ്കാരം പതിവാക്കിയാൽ അവന്റെ പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്. അത് സമുദ്ര നുരക്ക് സമാനമാണെങ്കിലും." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى حَتَّى نَقُولَ لَا يَدَعُ، وَيَدَعُهَا حَتَّى نَقُولَ لَا يُصَلِّي. حَسَنٌ غَرِيبٌ. (ت)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ''ഇനി അത് പ്രവാചകൻ(സ) ഉപേക്ഷിക്കുകയില്ല.'' എന്ന് ഞങ്ങൾ പറയുമാറ് നബി(സ) ളുഹാ നിസ്കരിച്ചിരിന്നു. ''ഇനി അത് പ്രവാചകൻ(സ) നിർവ്വഹിക്കുകയില്ല'' എന്ന് പറയുമാറ് അതിനെ ഉപേക്ഷിക്കുകയും ചെയ്തിരുന്നു. ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു. (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى أَرْبَعًا، وَيَزِيدُ مَا شَاءَ اللهُ. (م,جه)', 'ആഇശ(റ): നബി(സ) നാല് റക്അത്ത് ളുഹാ നിസ്കരിച്ചു. അല്ലാഹു ഉദ്ദേശിച്ചത്ര അത് വർദ്ധിപ്പിക്കുകയും ചെയ്തു. (മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَبْدِ اللهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ قَالَ: سَأَلْتُ وَحَرَصْتُ عَلَى أَنْ أَجِدَ أَحَدًا مِنَ النَّاسِ يُخْبِرُنِي: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَبَّحَ سُبْحَةَ الضُّحَى، فَلَمْ أَجِدْ أَحَدًا يُحَدِّثُنِي عَنْ ذَلِكَ، غَيْرَ أَنَّ أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ أَخْبَرَتْنِي: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَتَى بَعْدَ مَا ارْتَفَعَ النَّهَارُ يَوْمَ الْفَتْحِ، فَأُتِيَ بِثَوْبٍ فَسُتِرَ عَلَيْهِ، فَاغْتَسَلَ، ثُمَّ قَامَ، فَرَكَعَ ثَمَانِيَ رَكَعَاتٍ، لَا أَدْرِي: أَقِيَامُهُ فِيهَا أَطْوَلُ أَمْ رُكُوعُهُ أَمْ سُجُودُهُ، كُلُّ ذَلِكَ مِنْهُ مُتَقَارِبٌ، قَالَتْ: فَلَمْ أَرَهُ سَبَّحَهَا قَبْلُ وَلَا بَعْدُ. (م,د,جه)', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിഥ്(റ): അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ളുഹാ നിസ്കരിച്ചിട്ടുണ്ടെന്ന് എന്നോട് പറഞ്ഞു തരാൻ വേണ്ടി ജനങ്ങളിൽ നിന്ന് ഒരാളെ കണ്ടെത്താൻ ഞാൻ അതിയായി ആഗ്രഹിക്കുകയും അന്വേഷിക്കുകയും ചെയ്തു. എന്നാൽ അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ് ഒഴികെ എനിക്കതു പറഞ്ഞു തരുന്ന മറ്റൊരാളെയും ഞാൻ കണ്ടില്ല. അവർ എന്നോട് ഇപ്രകാരം അറിയിച്ചു: മക്കാവിജയ ദിനത്തിൽ അല്ലാഹുവിന്റെ റസൂൽ(സ) പകലുദിച്ചുയർന്ന ശേഷം (എന്റെ വീട്ടിലേക്ക്) വന്നു, അപ്പോൾ തിരുമേനി(സ)യിലേക്ക് വസ്ത്രം കൊണ്ടു വരുകയും, അതു കൊണ്ട് തിരുമേനി(സ)ക്കു മറച്ചു കൊടുക്കുകയും, അവിടുന്ന് കുളിക്കുകയും, അനന്തരം എഴുന്നേറ്റ് എട്ടു റക്അത്തുകൾ നിസ്കരിക്കുകയും ചെയ്തു. അതിൽ തിരുമേനി(സ)യുടെ നിർത്തമായിരുന്നുവോ, അതോ റുകൂആയിരുന്നുവോ, അതല്ലെങ്കിൽ സുജൂദായിരുന്നുവോ ദൈർഘ്യമേറിയത് എന്ന് എനിക്കറിയില്ല. അവയെല്ലാം തന്നെ ഏറെക്കുറെ തുല്യമായിരുന്നു. അവർ പറഞ്ഞു: ആ സംഭവത്തിനു മുമ്പോ ശേഷമോ തിരുമേനി(സ) ദുഹാ നിസ്കരിച്ചതായി ഞാൻ കണ്ടിട്ടില്ല. (മു,ദ,ജ)', 'عَبْدِ اللهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിഥ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ الْقَاسِمِ الشَّيْبَانِيِّ: أَنَّ زَيْدَ ابْنَ أَرْقَمَ رَضِيَ اللهُ عَنْهُ رَأَى قَوْمًا يُصَلُّونَ مِنَ الضُّحَى، فَقَالَ: أَمَا لَقَدْ عَلِمُوا أَنَّ الصَّلَاةَ فِي غَيْرِ هَذِهِ السَّاعَةِ أَفْضَلُ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلَاةُ الْأَوَّابِينَ حِينَ تَرْمَضُ الْفِصَالُ". (م)', 'ഖാസിം ശൈബാനി(റ): ഒരു ജനത ളുഹാ നിസ്കാരം നിർവ്വഹിക്കുന്നത് സൈദ്ബ്നു അർഖം(റ) കണ്ടു. അന്നേരം അദ്ദേഹം പറഞ്ഞു: ഈ നിസ്കാരം ഇതല്ലാത്ത സമയത്ത് നിർവ്വഹിക്കലാണ് കൂടുതൽ ശ്രേഷ്ടമായത് എന്നത് അവർക്കറിയില്ലേ? നിശ്ചയം അല്ലാഹുവിന്റെ ദൂതൻ(സ) അരുളി: "പശ്ചാതപിച്ചു മടങ്ങുന്നവരുടെ നിസ്കാരം ഒട്ടകക്കുഞ്ഞുങ്ങൾ ചുടിനാൽ എരിഞ്ഞു പൊള്ളുന്ന സമയത്താകുന്നു." (മു)', 'الْقَاسِمِ الشَّيْبَانِيِّ', 'ഖാസിം ശൈബാനി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُصْبِحُ عَلَى كُلِّ سُلَامَى مِنِ ابْنِ آدَمَ صَدَقَةٌ: تَسْلِيمُهُ عَلَى مَنْ لَقِيَ صَدَقَةٌ، وَأَمْرُهُ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيُهُ عَنِ الْمُنْكَرِ صَدَقَةٌ، وَإِمَاطَتُهُ الْأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ، وَبُضْعَةُ أَهْلِه صَدَقَةٌ، وَيُجْزِئُ مِنْ ذَلِكَ كُلِّه رَكْعَتَانِ مِنَ الضُّحَى". وَفِي رِوَايَةٍ: قَالُوا: يَا رَسُولَ اللهِ، أَحَدُنَا يَقْضِي شَهْوَتَهُ، وَتَكُونُ لَهُ صَدَقَةٌ؟ قَالَ: "أَرَأَيْتَ لَوْ وَضَعَهَا فِي غَيْرِ حِلِّهَا أَلَمْ يَكُنْ يَأْثَمُ". (د)', 'അബൂദർറ്(റ): പ്രവാചകൻ(സ) അരുളി: "മനുഷ്യന്റെ ഓരോ അവയവത്തിനും ധർമ്മമുണ്ട്. കണ്ടുമുട്ടിയവനോട് സലാം ചൊല്ലൽ ധർമ്മമാണ്. നന്മ കൽപ്പിക്കൽ ധർമ്മമാണ്, തിന്മ വിരോധിക്കലും ധർമ്മമാണ്. വഴിയിൽ നിന്നും മാലിന്യങ്ങൾ നീക്കം ചെയ്യൽ ധർമ്മമാണ്. ഒരാൾ തന്റെ സഹധർമ്മിണിയുമായി ലൈംഗികബന്ധത്തിലേർപ്പെടുന്നതും ധർമ്മമാണ്. രണ്ടു രക്അത്ത് ളുഹാ നിസ്കാരം അവയ്ക്കൊല്ലാം പകരമാകുന്നതാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ സഹാബികൾ ചോദിച്ചു: റസൂലേ, ഒരാൾ തന്റെ കാമപൂർത്തി നിർവ്വഹിക്കുന്നതും ധർമ്മമാണോ? തിരുമേനി(സ) പറഞ്ഞു: "ഒരാൾ അനുവദനീയമല്ലാത്ത വിധത്തിൽ ലൈംഗിക വേഴ്ച നടത്തുകയാണെങ്കിൽ പാപമാവുയില്ലേ? നിങ്ങൾ എന്തഭിപ്രായപ്പെടുന്നു." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=18), 1, 'وَفِي رِوَايَةٍ: قَالُوا: يَا رَسُولَ اللهِ، أَحَدُنَا يَقْضِي شَهْوَتَهُ، وَتَكُونُ لَهُ صَدَقَةٌ؟ قَالَ: "أَرَأَيْتَ لَوْ وَضَعَهَا فِي غَيْرِ حِلِّهَا أَلَمْ يَكُنْ يَأْثَمُ". (د)', 'മറ്റൊരു നിവേദനിൽ സഹാബികൾ ചോദിച്ചു: റസൂലേ, ഒരാൾ തന്റെ കാമപൂർത്തി നിർവ്വഹിക്കുന്നതും ധർമ്മമാണോ? തിരുമേനി(സ) പറഞ്ഞു: "ഒരാൾ അനുവദനീയമല്ലാത്ത വിധത്തിൽ ലൈംഗിക വേഴ്ച നടത്തുകയാണെങ്കിൽ പാപമാവുയില്ലേ? നിങ്ങൾ എന്തഭിപ്രായപ്പെടുന്നു." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي الْأَسْوَدِ الدُّؤَلِيِّ قَالَ: بَيْنَمَا نَحْنُ عِنْدَ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: "يُصْبِحُ عَلَى كُلِّ سُلَامَى مِنْ أَحَدِكُمْ فِي كُلِّ يَوْمٍ صَدَقَةٌ، فَلَهُ بِكُلِّ صَلَاةٍ صَدَقَةٌ، وَصِيَامٍ صَدَقَةٌ، وَحَجٍّ صَدَقَةٌ، وَتَسْبِيحٍ صَدَقَةٌ، وَتَكْبِيرٍ صَدَقَةٌ، وَتَحْمِيدٍ صَدَقَةٌ". فَعَدَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ هَذِهِ الْأَعْمَالِ الصَّالِحَةِ، ثُمَّ قَالَ: "يُجْزِئُ أَحَدَكُمْ مِنْ ذَلِكَ رَكْعَتَا الضُّحَى". (م,د)', 'അബുൽ അസ്വദുദ്ദുഅലി(റ): ഞങ്ങൾ അബൂദർറ്(റ)വിന്റെ അടുത്തുള്ളപ്പോൾ അദ്ദേഹം പറഞ്ഞു: "നിങ്ങളിൽ ഓരോരുത്തർക്കും ഓരോ ദിനത്തിലും ധർമ്മമുണ്ട്. അവന് ഓരോ നിസ്കാരവും ധർമ്മമാണ്. ഓരോ നോമ്പും ധർമ്മമാണ്. ഓരോ ഹജ്ജും ധർമ്മമാണ്. ഓരോ ദൈവസേതാത്രം ചെയ്യലും ധർമ്മമാണ്. ഓരോ തക്ബീറും ധർമ്മമാണ്. ഓരോ സ്തുതിയും ധർമ്മമാണ്." തിരുമേനി(സ) ഇത്തരത്തിലുള്ള സൽക്കർമ്മങ്ങളെയെല്ലാം എണ്ണിപ്പറഞ്ഞു. ശേഷം ഇപ്രകാരം പറഞ്ഞു: "ഇവക്ക് രണ്ട് റക്അത്ത് ദുഹാ നിസ്കാരം പകരമാകും." (മു,ദ)', 'أَبِي الْأَسْوَدِ الدُّؤَلِيِّ قَالَ', 'അബുൽ അസ്വദുദ്ദുഅലി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَعَدَ فِي مُصَلَّاهُ حِينَ يَنْصَرِفُ مِنْ صَلَاةِ الصُّبْحِ حَتَّى يُسَبِّحَ رَكْعَتَيِ الضُّحَى، لَا يَقُولُ إِلَّا خَيْرًا، غُفِرَ لَهُ خَطَايَاهُ، وَإِنْ كَانَتْ أَكْثَرَ مِنْ زَبَدِ الْبَحْرِ". (د)', 'മുആദുബ്നുഅനസ്(റ): തിരുമേനി(സ) പറഞ്ഞു: "ഒരാൾ സുബ്ഹ് നിസ്കാരത്തിൽ നിന്നും വിരമിച്ച് നിസ്കരിച്ച സ്ഥാനത്തുതന്നെയിരിക്കുകയും, ദുഹാ നിസ്കരിക്കുകയും, (അതിന്നിടയിൽ) നല്ലതു മാത്രം സംസാരിക്കുകയും ചെയ്താൽ അവന് തന്റെ പാപങ്ങൾ പൊറുത്തു കൊടുക്കുന്നതാണ്. അത് സമുദ്രത്തിലെ നുരയോളമുണ്ടെങ്കിലും ശരി." (ദ)', 'مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ', 'മുആദുബ്നുഅനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلَاةٌ فِي إِثْرِ صَلَاةٍ، لَا لَغْوَ بَيْنَهُمَا، كِتَابٌ فِي عِلِّيِّينَ". (ن)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു നിസ്കാരം (നിർവ്വഹിച്ചു) കഴിഞ്ഞ് മറ്റൊരു നിസ്കാരം (നിർവ്വഹിക്കും) വരെ ഒരാൾ യാതൊരു ദോഷവും ചെയ്യാതിരുന്നാൽ അത് ''ഇല്ലിയ്യീനി''ൽ രേഖപ്പെടുത്തപ്പെടും." (ന)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ نُعَيْمِ بْنِ هَمَّارٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَقُولُ اللهُ عَزَّ وَجَلَّ: يَا ابْنَ آدَمَ، لَا تُعْجِزْنِي مِنْ أَرْبَعِ رَكَعَاتٍ فِي أَوَّلِ نَهَارِكَ، أَكْفِكَ آخِرَهُ". (د)', 'നുഐമുബ്നു ഹമ്മാസ്(റ): പ്രവാചകൻ(സ) ഇപ്രകാരം പറയുന്നതു ഞാൻ കേട്ടു: "അല്ലാഹു പറയുന്നു: ആദമിന്റെ പുത്രാ! നീ പകലിന്റെ ആദ്യത്തിൽ എനിക്കു വേണ്ടി നാലു റക്അത്തുകൾ നിസ്കരിക്കാൻ അശക്തനായിപ്പോകരുത്. എങ്കിൽ അതിന്റെ അവസാനം വരെ നിനക്കാവശ്യമായത് ഞാൻ നൽകും." (ദ)', 'نُعَيْمِ بْنِ هَمَّارٍ', 'നുഐമുബ്നു ഹമ്മാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْفَتْحِ صَلَّى سُبْحَةَ الضُّحَى ثَمَانِيَ رَكَعَاتٍ، يُسَلِّمُ مِنْ كُلِّ رَكْعَتَيْنِ. (ق,د,ت,ن,جه)', 'ഉമ്മുഹാനിഅ്(റ): പ്രവാചകൻ(സ) മക്കാവിജയദനത്തിൽ എട്ടു റക്അത്ത് ദുഹാനിസ്കാരം നിർവ്വഹിക്കുകയുണ്ടായി. ഈരണ്ടു റക്അത്തുകളിൽ അവിടുന്ന് സലാം ചൊല്ലിയിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَقَدْ سُئِلَتْ: هَلْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى؟ فَقَالَتْ: لَا، إِلَّا أَنْ يَجِيءَ مِنْ مَغِيبِه. وَسُئِلَتْ: هَلْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرِنُ بَيْنَ السُّورَتَيْنِ؟ قَالَتْ: مِنَ الْمُفَصَّلِ. (د)', 'ആഇശ(റ): അവർ ചോദിക്കപ്പെട്ടു: പ്രവാചകൻ(സ) ദുഹാ നിസ്കാരം നിർവ്വഹിച്ചിരുന്നുവോ? അവർ പറഞ്ഞു: ഇല്ല, യാത്ര കഴിഞ്ഞ് തിരിച്ചെത്തിയാൽ ഒഴികെ. അവരോട് ചോദിച്ചു: തിരുമേനി(സ) രണ്ട് തുല്യമായ സൂറത്തുകൾ ഓതാറുണ്ടോ? അവർ പറഞ്ഞു: അതെ, ''മുഫസ്സലു''കളിൽ നിന്നാണ് ഓതുക. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – أَنَّهَا قَالَتْ: مَا سَبَّحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُبْحَةَ الضُّحَى قَطُّ، وَإِنِّي لَأُسَبِّحُهَا. وَإِنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيَدَعُ الْعَمَلَ – وَهُوَ يُحِبُّ أَنْ يُعْمَلَ بِه – خَشْيَةَ أَنْ يَعْمَلَ بِه النَّاسُ فَيُفْرَضَ عَلَيْهِمْ. (ق,د)', 'പ്രവാചക പത്നി ആഇശ(റ): പ്രവാചകൻ(സ) ഓരിക്കലും ദുഹാനിസ്കാരം നിർവ്വഹിച്ചിട്ടില്ല. ഞാൻ അത് നിർവ്വഹിക്കാറുണ്ട്. തിരുമേനി(സ) അനുഷ്ടിക്കാൻ ഇഷ്ടപ്പെട്ടിട്ടും ചിലകർമ്മങ്ങൾ ഉപേക്ഷിക്കാറുണ്ടായിരുന്നു. ജനങ്ങൾ അത് അനുഷ്ടിക്കുകയും, അങ്ങനെ അല്ലാഹു അത് നിർബന്ധകർമ്മമായി നിശ്ചയക്കുകയും ചെയ്തേക്കാം എന്ന ഭയത്താലായിരുന്നു ഇത്. (ബു,മു,ദ)', 'عَائِشَةَ', 'പ്രവാചക പത്നി ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ: وَقَدْ سُئِلَ: أَكُنْتَ تُجَالِسُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ كَثِيرًا، فَكَانَ لَا يَقُومُ مِنْ مُصَلَّاهُ الَّذِي صَلَّى فِيهِ الْغَدَاةَ حَتَّى تَطْلُعَ الشَّمْسُ، فَإِذَا طَلَعَتْ قَامَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ن)', 'ജാബിറുബ്സറുമ(റ): അദ്ദേഹത്തോട് ചോദിച്ചു: താങ്കൾ പ്രവാചകനോടൊന്നിച്ചിരിക്കാറുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, ധാരാളമായി ഉണ്ട്. തിരുമേനി(സ) പ്രഭാതനിസ്കാരം നിർവ്വഹിച്ചേടത്തുനിന്ന് സൂര്യനുദിക്കും വരെ എഴുന്നേൽക്കാറില്ല. സൂര്യനുദിച്ചു കഴിഞ്ഞാൽ അവിടുന്ന് (നിസ്കരിക്കാൻ) എഴുന്നേൽക്കും. (മു,ദ,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്സറുമ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الرَّكْعَتَيْنِ قَبْلَ الْغَدَاةِ، كَأَنَّ الْأَذَانَ بِأُذُنَيْهِ. (جه)', 'ഇബ്നു ഉമർ(റ): ബാങ്ക് നബി(സ)യുടെ ചെവിയിലുണ്ടായിരിക്കെ (ബാങ്ക് കേട്ടുകൊണ്ട്) നബി(സ) സുബ്ഹിന്റെ സുന്നത്ത് നിസ്കരിക്കുമായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا تَوَضَّأَ صَلَّى رَكْعَتَيْنِ، ثُمَّ خَرَجَ إِلَى الصَّلَاةِ. (جه)', 'ആഇശ(റ): നബി(സ) അംഗശുദ്ധി വരുത്തിയാൽ രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും, തുടർന്ന് (ഫർള്) നിസ്കാരത്തിനായി പുറപ്പെടുകയും ചെയ്യുമായിരുന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الرَّكْعَتَيْنِ عِنْدَ الْإِقَامَةِ. (جه)', 'അലി(റ): നബി(സ) ഇഖാമത്തിന്റെ വേളയിൽ (തൊട്ടുമുമ്പ്) രണ്ട് റക്അത്ത് നിസ്കാരം നിർവ്വഹിച്ചിരുന്നു. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 527, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا". (م,ت,ن)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ഫജ്റിന്റെ രണ്ട് റക്അത്ത് ഈ ലോകവും അതിലുള്ള എല്ലാറ്റിനേക്കാളും ഉത്തമമത്രെ." (മു,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا صَلَّى أَحَدُكُمُ الرَّكْعَتَيْنِ قَبْلَ الصُّبْحِ فَلْيَضْطَجِعْ عَلَى يَمِينه". فَقَالَ لَهُ مَرْوَانُ بْنُ الْحَكَمِ: أَمَا يُجْزِئُ أَحَدَنَا مَمْشَاهُ إِلَى الْمَسْجِدِ حَتَّى يَضْطَجِعَ عَلَى يَمِينه؟ قَالَ: لَا، قَالَ: فَبَلَغَ ذَلِكَ ابْنَ عُمَرَ فَقَالَ: أَكْثَرَ أَبُو هُرَيْرَةَ عَلَى نَفْسه، قَالَ: فَقِيلَ لِابْنِ عُمَرَ: هَلْ تُنْكِرُ شَيْئًا مِمَّا يَقُولُ؟قَالَ: لَا، وَلَكِنَّهُ اجْتَرَأَ وَجَبُنَّا. قَالَ: فَبَلَغَ ذَلِكَ أَبَا هُرَيْرَةَ، قَالَ: فَمَا ذَنْبِي إِنْ كُنْتُ حَفِظْتُ وَنَسُوا. (د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ സുബ്ഹിക്കു മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിച്ചാൽ ശേഷം വലത് ഭാഗത്തേക്ക് ചെരിഞ്ഞ് കിടക്കട്ടെ." അപ്പോൾ മർവാൻ അബൂഹുറൈറ(റ)വിനോട് ചോദിച്ചു: വലതു ഭാഗത്തേക്കു ചെരിഞ്ഞു കിടക്കുന്നതിനുപകരംഞങ്ങളിലൊരാൾക്ക് പള്ളിയിലേക്കുള്ള നടത്തം മതിയാവുമോ? അബൂഹുറൈറ(റ) പറഞ്ഞു: മതിയാവില്ല. ഇത് ഇബ്നു ഉമർ(റ) അറിയാനിടയായി. അദ്ദേഹം പറഞ്ഞു: അബൂഹുറൈറ വർദ്ധിപ്പിച്ചിരിക്കുന്നു. അപ്പോൾ ഇബ്നു ഉമറി(റ)നോട് ചോദിക്കപ്പെട്ടു: അദ്ദേഹം (അബൂഹുറൈറ) പറഞ്ഞതിൽ വല്ലതും നിങ്ങൾ നിഷേധിക്കുന്നുണ്ടോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: ഇല്ല. പക്ഷെ, അദ്ദേഹം ധൈര്യം കാണിച്ചു, ഞങ്ങൾ ഭീരുക്കളായി. ഇക്കാര്യം അബൂഹുറൈറ(റ) അറിയാനിടയായി. അദ്ദേഹം പറഞ്ഞു: ഞാൻ മനഃപാഠമാക്കിയതും, അവർ അത് മറന്നതും എന്റെ കുറ്റമല്ല. (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَضَى صَلَاتَهُ مِنْ آخِرِ اللَّيْلِ نَظَرَ، فَإِنْ كُنْتُ مُسْتَيْقِظَةً حَدَّثَنِي، وَإِنْ كُنْتُ نَائِمَةً أَيْقَظَنِي، وَصَلَّى الرَّكْعَتَيْنِ، ثُمَّ اضْطَجَعَ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ فَيُؤْذِنَهُ بِصَلَاةِ الصُّبْحِ، فَيُصَلِّي رَكْعَتَيْنِ خَفِيفَتَيْنِ، ثُمَّ يَخْرُجُ إِلَى الصَّلَاةِ. (ق,د,ت)', 'ആഇശ(റ): നബി(സ) തന്റെ നിശാ നിസ്കാരശേഷം വീക്ഷിക്കും. ഞാൻ എഴുന്നേറ്റിട്ടുണ്ടെങ്കിൽ എന്നോട് സംസാരിക്കുകയും ഉറക്കിലാണെങ്കിൽ എന്നെ ഉണർത്തുകയും ചെയ്യും. തുടർന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും പിന്നെ മുഅദ്ദിൻ വരുന്നതുവരെ ചെരിഞ്ഞ് കിടക്കുകയും ചെയ്യുമായിരുന്നു. തുടർന്ന് മുഅദ്ദിൻ സുബ്ഹി നിസ്കാരം അറിയിക്കുകയും നബി(സ) ലഘുവായി രണ്ട് റക്അത്തുകൾ നമസ്കരിക്കുകയും തുടർന്ന് ഫർദ് നിസ്കരിക്കുകയും ചെയ്യുമായിരുന്നു. (ബു,മു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى رَكْعَتَيِ الْفَجْرِ: فَإِنْ كُنْتُ نَائِمَةً اضْطَجَعَ، وَإِنْ كُنْتُ مُسْتَيْقِظَةً حَدَّثَنِي. (د)', 'ആഇശ(റ): നബി(സ) സുബ്ഹിയുടെ രണ്ട് റക്അത്ത് (സുന്നത്ത്) നിസ്കരിച്ച ശേഷം ഞാൻ ഉറക്കത്തിലാണെങ്കിൽ കിടക്കുകയും, ഞാൻ ഉണർന്നിരിക്കുകയാണെങ്കിൽ എന്നോട് സംസാരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِصَلَاةِ الصُّبْحِ، فَكَانَ لَا يَمُرُّ بِرَجُلٍ إِلَّا نَادَاهُ أَوْ حَرَّكَهُ بِرِجْلِه. (د)', 'അബീബകറത്ത്(റ): ഞാൻ നബി(സ)യോടൊത്ത് സുബ്ഹി നിസ്കാരത്തിന്ന് പുറപ്പെട്ടപ്പോൾ വഴിയിലുള്ളവരെ വിളിക്കുകയോ കാൽ കൊണ്ട് അനക്കുകയോ ചെയ്യാതെ നബി(സ) നടന്നിട്ടില്ല. (ദ)', 'أَبِي بَكْرَةَ', 'അബീബകറത്ത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَبْدِ اللهِ بْنِ سَرْجِسَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الصُّبْحَ، فَصَلَّى الرَّكْعَتَيْنِ، ثُمَّ دَخَلَ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الصَّلَاةِ، فَلَمَّا انْصَرَفَ قَالَ: "يَا فُلَانُ، أَيَّتُهُمَا صَلَاتُكَ: الَّتِي صَلَّيْتَ وَحْدَكَ، أَوِ الَّتِي صَلَّيْتَ مَعَنَا؟". (م,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ): നബി(സ) സുബ്ഹ് നിസ്കരിക്കുമ്പോൾ ഒരാൾ പള്ളിയിൽ വന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ശേഷം നബി(സ)യോടൊത്ത് സുബ്ഹ് നിസ്കാരത്തിൽ പ്രവേശിച്ചു. അയാൾ നിസ്കാരത്തിൽ നിന്നും വിരമിച്ചപ്പോൾ നബി(സ) ചോദിച്ചു: "ഓ മനുഷ്യാ, ഏതാണ് നിന്റെ നിസ്കാരം, നീ തനിയെ നിസ്കരിച്ചതോ, അതോ നമ്മോടൊത്ത് നിർവ്വഹിച്ചതോ?" (മു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ سَرْجِسَ', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمْ يَكُنِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى شَيْءٍ مِنَ النَّوَافِلِ، أَشَدَّ مِنْهُ تَعَاهُدًا عَلَى رَكْعَتَيِ الْفَجْرِ. (خ,د,ن)', 'ആഇശ(റ): സുന്നത്ത് നിസ്കാരങ്ങളിൽ വെച്ച് സുബ്ഹിയുടെ രണ്ട് റക്അത്തിന്റെ കാര്യത്തിൽ ശ്രദ്ധ കാണിക്കുന്നത്ര ഗൗരവമായി നബി(സ) മറ്റൊരു സുന്നത്തിലും ശ്രദ്ധ ചെലുത്താറുണ്ടായിരുന്നില്ല. (ബു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ قَيْسِ بْنِ عَمْرو رَضِيَ اللهُ عَنْهُ قَالَ: رَأَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يُصَلِّي بَعْدَ صَلَاةِ الصُّبْحِ رَكْعَتَيْنِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصَلَاةَ الصُّبْحِ مَرَّتَيْنِ؟". فَقَالَ لَهُ الرَّجُلُ: إِنِّي لَمْ أَكُنْ صَلَّيْتُ الرَّكْعَتَيْنِ اللَّتَيْنِ قَبْلَهَا فَصَلَّيْتُهُمَا. قَالَ: فَسَكَتَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د,ت,جه)', 'ഖൈസുബ്നു അംറ്(റ): സുബ്ഹ്ന് ശേഷം രണ്ട് റക്അത്ത് നിസ്കരിച്ച ഒരാളെ നബി(സ) കണ്ടു. നബി(സ) അയാളോട് ചോദിച്ചു: "സുബ്ഹി നിസ്കാരം രണ്ട് പ്രാവശ്യമോ?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ സുബ്ഹിക്ക് മുമ്പുള്ള രണ്ട് റക്അത്ത് നിർവ്വഹിച്ചിരുന്നില്ല. അതാണിപ്പോൾ നിർവ്വഹിച്ചത്. റിപ്പോർട്ടർ പറയുന്നു: അപ്പോൾ നബി(സ) മൗനം പാലിച്ചു. (ദ,തു,ജ)', 'قَيْسِ بْنِ عَمْرو', 'ഖൈസുബ്നു അംറ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَامَ عَنْ رَكْعَتَيِ الْفَجْرِ، فَقَضَاهُمَا بَعْدَ مَا طَلَعَتِ الشَّمْسُ. [ز: في إسناده مدلس عنعنه] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) സുബ്ഹിന്റെ രണ്ട് റക്അത്ത് നിർവ്വഹിക്കാതെ ഉറങ്ങിപ്പോയി. പിന്നീട് സൂര്യോദയശേഷം അവ നിർവ്വഹിച്ചു. (ഇതിന്റെ പരമ്പരയിൽ ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുണ്ടെന്ന് ഇബ്നു മാജ പറയുന്നു) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مدلس عنعنه', null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأُقِيمَتِ الصَّلَاةُ، فَصَلَّيْتُ مَعَهُ الصُّبْحَ، ثُمَّ انْصَرَفَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَنِي أُصَلِّي، فَقَالَ: "مَهْلًا يَا قَيْسُ، أَصَلَاتَانِ مَعًا". قُلْتُ: يَا رَسُولَ اللهِ، إِنِّي لَمْ أَكُنْ رَكَعْتُ رَكْعَتَيِ الْفَجْرِ. قَالَ: "فَلَا إِذَنْ". (ت)', 'ഖൈസ്(റ): നബി(സ) പുറപ്പെട്ട് ഇഖാമത്ത് കൊടുക്കപ്പെട്ടപ്പോൾ ഞാൻ നബി(സ)യോടൊപ്പം സുബ്ഹ് നിസ്കരിച്ചു. നബി(സ) മടങ്ങിപ്പോവുമ്പോൾ ഞാൻ നിസ്കരിക്കുന്നതു കണ്ടു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "ഓ ഖൈസേ, നിൽക്കൂ. രണ്ട് നിസ്കാരങ്ങൾ ഒന്നിച്ചോ?" ഞാൻ പറഞ്ഞു: പ്രവാചകരേ, ഞാൻ ഫജ്റിന്റെ രണ്ട് റക്അത്ത് നിസ്കരിച്ചിരുന്നില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എങ്കിൽ കുഴപ്പമില്ല." (തു)', 'قَيْسٍ', 'ഖൈസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَمْ يُصَلِ رَكْعَتَيِ الْفَجْرِ فَلْيُصَلِّهِمَا بَعْدَ مَا تَطْلُعُ الشَّمْسُ". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഫജ്റിന്റെ രണ്ട് റക്അത്ത് നിർവ്വഹിക്കാത്തവൻ സൂര്യോദയ ശേഷം അവരണ്ടും നിർവ്വഹിക്കട്ടെ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 529, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنْ حَفْصَةَ أُمِّ الْمُؤْمِنِينَ رَضِيَ اللهُ عَنْهَا أَنَّهَا أَخْبَرَتْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَكَتَ الْمُؤَذِّنُ، صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ. وَفِي رِوَايَةٍ: كَانَ إِذَا سَكَتَ الْمُؤَذِّنُ مِنَ الْأَذَانِ لِصَلَاةِ الصُّبْحِ، صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ تُقَامَ الصَّلَاةُ. وَفِي رِوَايَةٍ: كَانَ يُصَلِّي قَبْلَ الْفَجْرِ رَكْعَتَيْنِ خَفِيفَتَيْنِ. وَفِي رِوَايَةٍ: كَانَ يُصَلِّي رَكْعَتَيْنِ إِذَا طَلَعَ الْفَجْرُ. وَفِي رِوَايَةٍ: إِذَا طَلَعَ الْفَجْرُ لَا يُصَلِّي إِلَّا رَكْعَتَيْنِ خَفِيفَتَيْنِ. وَفِي رِوَايَةٍ: أَنَّهُ كَانَ إِذَا نُودِيَ لِصَلَاةِ الصُّبْحِ رَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ يَقُومَ إِلَى الصَّلَاةِ. وَفِي رِوَايَةٍ: كَانَ يَرْكَعُ رَكْعَتَيْنِ قَبْلَ الْفَجْرِ، وَذَلِكَ بَعْدَ مَا يَطْلُعُ الْفَجْرُ. وَفِي رِوَايَةٍ: كَانَ إِذَا أَضَاءَ لَهُ الْفَجْرُ صَلَّى رَكْعَتَيْنِ. وَفِي رِوَايَةٍ: كَانَ يُصَلِّي رَكْعَتَيْنِ خَفِيفَتَيْنِ، بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الْفَجْرِ. (ن,جه)', 'ഇബ്നു ഉമർ(റ): ഉമ്മുൽ മുഅ്മിനീൻ ഹഫ്സ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: മുഅദ്ദിൻ ബാങ്ക് അവസാനിപ്പിച്ചാൽ നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കും. മറ്റൊരു റിപ്പോർട്ടിൽ: സുബ്ഹ് ബാങ്കിൽ നിന്ന് മുഅദ്ദിൻ വിരമിച്ചാൽ നിസ്കാരം നിർവ്വഹിക്കപ്പെടുന്നതിനുമുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കും. മറ്റൊരു റിപ്പോർട്ടിൽ: ഫജ്റ് നിസ്കാരത്തിനു മുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഫജ്റ് ഉദിച്ചാൽ നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: സുബ്ഹ് നിസ്കാരത്തിന് ബാങ്ക് വിളിക്കപ്പെട്ടാൽ നിസ്കരിക്കുന്നതിനു മുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിർവ്വഹിക്കാറുണ്ടായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഫജ്റ് നിസ്കാരത്തിനു മുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. അത് ഫജ്റ് ഉദിച്ച ശേഷമാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ: ഫജ്റ് വെളിവായാൽ നബി(സ) രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: സുബ്ഹ് നിസ്കാരത്തിന്റെ ബാങ്കിനും ഇഖാമത്തിനുമിടയിൽ ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. (ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 1, 'وَفِي رِوَايَةٍ: كَانَ إِذَا سَكَتَ الْمُؤَذِّنُ مِنَ الْأَذَانِ لِصَلَاةِ الصُّبْحِ، صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ تُقَامَ الصَّلَاةُ.', 'മറ്റൊരു നിവേദനിൽ: സുബ്ഹ് ബാങ്കിൽ നിന്ന് മുഅദ്ദിൻ വിരമിച്ചാൽ നിസ്കാരം നിർവ്വഹിക്കപ്പെടുന്നതിനുമുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കും.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 2, 'وَفِي رِوَايَةٍ: كَانَ يُصَلِّي قَبْلَ الْفَجْرِ رَكْعَتَيْنِ خَفِيفَتَيْنِ.', 'മറ്റൊരു നിവേദനിൽ: ഫജ്റ് നിസ്കാരത്തിനു മുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 3, 'وَفِي رِوَايَةٍ: كَانَ يُصَلِّي رَكْعَتَيْنِ إِذَا طَلَعَ الْفَجْرُ.', 'മറ്റൊരു നിവേദനിൽ: ഫജ്റ് ഉദിച്ചാൽ നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 4, 'وَفِي رِوَايَةٍ: إِذَا طَلَعَ الْفَجْرُ لَا يُصَلِّي إِلَّا رَكْعَتَيْنِ خَفِيفَتَيْنِ.', 'മറ്റൊരു നിവേദനിൽ: സുബ്ഹ് നിസ്കാരത്തിന് ബാങ്ക് വിളിക്കപ്പെട്ടാൽ നിസ്കരിക്കുന്നതിനു മുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിർവ്വഹിക്കാറുണ്ടായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 5, 'وَفِي رِوَايَةٍ: أَنَّهُ كَانَ إِذَا نُودِيَ لِصَلَاةِ الصُّبْحِ رَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ يَقُومَ إِلَى الصَّلَاةِ.', 'മറ്റൊരു നിവേദനിൽ: ഫജ്റ് നിസ്കാരത്തിനു മുമ്പ് നബി(സ) ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. അത് ഫജ്റ് ഉദിച്ച ശേഷമാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 6, 'وَفِي رِوَايَةٍ: كَانَ يَرْكَعُ رَكْعَتَيْنِ قَبْلَ الْفَجْرِ، وَذَلِكَ بَعْدَ مَا يَطْلُعُ الْفَجْرُ.', 'മറ്റൊരു നിവേദനിൽ: ഫജ്റ് വെളിവായാൽ നബി(സ) രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 7, 'وَفِي رِوَايَةٍ: كَانَ إِذَا أَضَاءَ لَهُ الْفَجْرُ صَلَّى رَكْعَتَيْنِ.', 'മറ്റൊരു നിവേദനിൽ: സുബ്ഹ് നിസ്കാരത്തിന്റെ ബാങ്കിനും ഇഖാമത്തിനുമിടയിൽ ലഘുവായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. (ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=41), 8, 'وَفِي رِوَايَةٍ: كَانَ يُصَلِّي رَكْعَتَيْنِ خَفِيفَتَيْنِ، بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الْفَجْرِ. (ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ قَالَتْ: كَانَ يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً: يُصَلِّي ثَمَانَ رَكَعَاتٍ، ثُمَّ يُوتِرُ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ. وَيُصَلِّي رَكْعَتَيْنِ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ فِي صَلَاةِ الصُّبْحِ. (ن)', 'ആഇശ(റ): നബി(സ)യുടെ രാത്രി നിസ്കാരത്തെക്കുറിച്ച് അവരോട് ചോദിക്കപ്പെട്ടു, അവർ പറഞ്ഞു: നബി(സ) പതിമൂന്ന് റക്അത്ത് നിസ്കരിക്കാറുണ്ട്. എട്ട് റക്അത്ത് നിസ്കരിക്കും. പിന്നെ വിത്റ് നിസ്കരിക്കും, പിന്നെ ഇരുന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കും. (നിസ്കാരത്തിനിടയിൽ) റുകൂഅ് ചെയ്യാനുദ്ദേശിച്ചാൽ എഴുന്നേറ്റ് നിന്ന ശേഷം റുകൂഅ് ചെയ്യും. സുബ്ഹ് നിസ്കാരത്തിൽ ബാങ്കിനും ഇഖാമത്തിനുമിടയിൽ രണ്ട് റക്അത്ത് നിസ്കരിക്കും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ: أَنَّ شُرَيْحًا الْحَضْرَمِيَّ ذُكِرَ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَتَوَسَّدُ الْقُرْآنَ". (ن)', 'സാഇബുബ്നു യസീദ്(റ): ശുറൈഹുൽ ഹള്റമിയെക്കുറിച്ച് നബി(സ)യുടെ അടുക്കൽ പരാമർശിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹം ഖുർആൻ തലയണയാക്കുന്നവനല്ല¹." (ന)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', '¹. ഖുർആനിനെ തലയണയാക്കുകയോ അതിനെ അവഗണിക്കുകയോ അതിലെ നിർദ്ദേശങ്ങൾക്കനുസരിച്ച് പ്രവർത്തിക്കാതിരിക്കുകയോ ചെയ്യുന്നവനല്ല ശുറൈഹുൽ ഹള്റമി എന്നാണ് ഇവിടെ ഉദ്ദേശിച്ചതതെന്ന് മനസ്സിലാക്കാം', null, array['ن']::text[], array['ന']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ بِلَالٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِيُؤْذِنَهُ بِصَلَاةِ الْغَدَاةِ، فَشَغَلَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا بِلَالًا بِأَمْرٍ سَأَلَتْهُ عَنْهُ، حَتَّى فَضَحَهُ الصُّبْحُ، فَأَصْبَحَ جِدًّا، قَالَ: فَقَامَ بِلَالٌ بِالصَّلَاةِ، وَتَابَعَ أَذَانَهُ، فَلَمْ يَخْرُجْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا خَرَجَ صَلَّى بِالنَّاسِ، وَأَخْبَرَهُ أَنَّ عَائِشَةَ شَغَلَتْهُ بِأَمْرٍ سَأَلَتْهُ عَنْهُ حَتَّى أَصْبَحَ جِدًّا، وَأَنَّهُ أَبْطَأَ عَلَيْهِ بِالْخُرُوجِ، فَقَالَ: "إِنِّي كُنْتُ رَكَعْتُ رَكْعَتَيِ الْفَجْرِ". فَقَالَ: يَا رَسُولَ اللهِ، إِنَّكَ أَصْبَحْتَ جِدًّا، قَالَ: "لَوْ أَصْبَحْتُ أَكْثَرَ مِمَّا أَصْبَحْتُ لَرَكَعْتُهُمَا وَأَحْسَنْتُهُمَا وَأَجْمَلْتُهُمَا". (د,جه)', 'ബിലാൽ(റ): അദ്ദേഹം നബി(സ)യുടെ അടുക്കൽ സുബ്ഹ് നിസ്കാരത്തെകുറിച്ച് അറിയിക്കുവാൻ ചെന്നു. അപ്പോൾ ആഇശ(റ) ബിലാലു(റ)മായി ഒരു ചോദ്യത്തിൽ ഏർപ്പെടുകയും പ്രഭാതം നന്നായി ഉദിക്കും വരെ അത് തുടരുകയും ചെയ്തു. അനന്തരം ബിലാൽ(റ) എഴുന്നേറ്റ് ബാങ്കും ഇഖാമത്തും വിളിച്ചു. അപ്പോൾ നബി(സ) വന്നിട്ടില്ലായിരുന്നു. ശേഷം തിരുമേനി(സ) പുറത്തുവന്നപ്പോൾ അവിടുന്ന് ജനങ്ങൾക്ക് ഇമാമായി നിസ്കാരം നിർവ്വഹിച്ചു. ''ആഇശ(റ) തന്നോട് ഒരു ചോദ്യത്തിൽ ഏർപ്പെട്ടതായും അങ്ങനെ നേരം പുലർന്നതായും അതിനാൽ തിരുമേനി(സ)യുടെ അടുത്തു ചെല്ലാൻ താമസിച്ചതായും ബിലാൽ(റ) നബി(സ)യെ അറിയിച്ചു''. നബി(സ) പറഞ്ഞു: "ഞാൻ സുബ്ഹ്ന് മുമ്പുള്ള രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ട്." അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: നേരം അധികം പുലർന്നില്ലേ? നബി(സ) പറഞ്ഞു: "ഞാൻ ഇതിനേക്കാൾ നേരം പുലർന്നാൽ പോലും ആ രണ്ട് റക്അത്തുകൾ വളരെ ചുരുക്കി നിസ്കരിക്കാറുണ്ട്." (ദ,ജ)', 'بِلَالٍ', 'ബിലാൽ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَدْعُوهُمَا وَإِنْ طَرَدَتْكُمُ الْخَيْلُ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആ രണ്ട് റക്അത്തുകൾ (സുബ്ഹ്ന് മുമ്പുള്ള) നിങ്ങൾ ഉപേക്ഷിക്കരുത്. അശ്വസേന നിങ്ങളെ വിരട്ടിയാലും ശരി." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ كَثِيرًا مِمَّا كَانَ يَقْرَأُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي رَكْعَتَيِ الْفَجْرِ بِ: {آمَنَّا بِاللهِ وَمَا أُنْزِلَ إِلَيْنَا} [البقرة:١٣٦] هَذِهِ الْآيَةُ، قَالَ: هَذِهِ فِي الرَّكْعَةِ الْأُولَى، وَفِي الرَّكْعَةِ الْآخِرَةِ بِ: {آمَنَّا بِاللهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ} [آل عمران:٥٢]. (د)', 'അബ്ദുല്ലാഹിബ്നി അബ്ബാസ്(റ): മിക്കപ്പോഴും നബി(സ) സുബ്ഹിന്റെ സുന്നത്തിൽ ആദ്യറക്അത്തിൽ ഓതാറുള്ളത്. آمنا بالله وما أنزل إلينا എന്ന ആയത്താണ്. രണ്ടാമത്തെ റക്അത്തിൽ ഓതാറുള്ളത് امنا بالله وأشهد بأنا مسلمون എന്ന ആയത്തുമാണ്. (ദ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നി അബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'آل عمران:٥٢', null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي رَكْعَتَيِ الْفَجْرِ: {قُلْ آمَنَّا بِاللهِ وَمَا أُنْزِلَ عَلَيْنَا } [آل عمران:٨٤] فِي الرَّكْعَةِ الْأُولَى، وَفِي الرَّكْعَةِ الْأُخْرَى بِهَذِهِ الْآيَةِ {رَبَّنَا آمَنَّا بِمَا أَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ} [آل عمران:٥٣] أَوْ: {إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ} [البقرة:١١٩] (د)', 'അബൂഹുറൈറ(റ): നബി(സ) സുബ്ഹ്ന്റെ രണ്ട് റക്അത്ത് സുന്നത്തിൽ ആദ്യറക്അത്തിൽ قل آمنا بالله (ആലുഇംറാൻ: 84)ഉം, രണ്ടാം റക്അത്തിൽ ربنا آمنا (ആലുഇംറാൻ: 53) അല്ലെങ്കിൽ إنا أرسلناك بالحق (അൽബഖറ: 119) എന്നിവ പാരായണം ചെയ്യുന്നത് അദ്ദേഹം കേട്ടു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'البقرة:١١٩', null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَمَقْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهْرًا، فَكَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ بِ {قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ{قُلْ هُوَ اللهُ أَحَدٌ}. حَسَنٌ. (م,د,ت,ن,جه)', 'ഇബ്നു ഉമർ(റ): ഞാൻ നബി(സ)യെ ഒരു മാസക്കാലം നിരീക്ഷിച്ചു, സുബ്ഹ്ന്റെ മുമ്പുള്ള സുന്നത്ത് നിസ്കാരത്തിൽ നബി(സ) ''قل يا أيها الكافرون، قل هو الله أحد'' എന്നീ സൂറത്തുകളാണ് ഓതിയിരുന്നത്. (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു) (മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 531, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي رَكْعَتَيْنِ قَبْلَ الْفَجْرِ، وَكَانَ يَقُولُ: "نِعْمَ السُّورَتَانِ هُمَا، يُقْرَأُ بِهِمَا فِي رَكْعَتَيِ الْفَجْرِ: {قُلْ هُوَ اللهُ أَحَدٌ} وَ{قُلْ يَا أَيُّهَا الْكَافِرُونَ}". (جه)', 'ആഇശ(റ): നബി(സ) സുബ്ഹ്ന് മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു, അവിടുന്ന് പറയും: "എന്തു നല്ല രണ്ട് സുറത്തുകളാണവ, സുബ്ഹ്ന്റെ സുന്നത്തിൽ ഓതാൻ പറ്റിയവയാണ് അവ. قل يا أيها الكافرون قل هو الله أحد എന്നിവയാണ് ആ സുറത്തുകൾ." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى رَكْعَتَيِ الْفَجْرِ: فَإِنْ كَانَتْ لَهُ إِلَيَّ حَاجَةٌ كَلَّمَنِي، وَإِلَّا خَرَجَ إِلَى الصَّلَاةِ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) സുബ്ഹ്ന് മുമ്പുള്ള രണ്ട് റക്അത്ത് നിസ്കരിച്ചാൽ എന്നോട് എന്തെങ്കിലും ആവശ്യമുണ്ടെങ്കിൽ സംസാരിക്കും, ഇല്ലെങ്കിൽ പള്ളിയിലേക്ക് പോവും. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةَ". (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇഖാമത്ത് വിളിക്കപ്പെട്ടാൽ ഫർള് ഒഴികെ മറ്റൊരു നിസ്കാരവുമില്ല." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَبْدِ اللهِ بْنِ سَرْجِسَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يُصَلِّي الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الْغَدَاةِ، وَهُوَ فِي الصَّلَاةِ، فَلَمَّا صَلَّى قَالَ لَهُ: "بِأَيِّ صَلَاتَيْكَ اعْتَدَدْتَ". (م,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ): സുബ്ഹിക്കു മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിക്കുന്ന ഒരാളെ നബി(സ) കണ്ടു. നബി(സ) അപ്പോൾ നിസ്കാരത്തിലായിരുന്നു. നിസ്കാരാനന്തരം നബി(സ) ചോദിച്ചു: "നിന്റെ നിസ്കാരങ്ങളിൽ ഏതിനെയാണ് നീ പരിഗണിച്ചത്?" (മു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ سَرْجِسَ', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَبْدِ اللهِ بْنِ مَالِكِ بْنِ بُحَيْنَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ وَقَدْ أُقِيمَتْ صَلَاةُ الصُّبْحِ، وَهُوَ يُصَلِّي، فَكَلَّمَهُ بِشَيْءٍ لَا أَدْرِي مَا هُوَ، فَلَمَّا انْصَرَفَ أَحَطْنَا بِهِ نَقُولُ لَهُ: مَاذَا قَالَ لَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: قَالَ لِي: "يُوشِكُ أَحَدُكُمْ أَنْ يُصَلِّيَ الْفَجْرَ أَرْبَعًا". (ق,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മാലികിബ്നു ബുജൈന(റ): സുബ്ഹി നിസ്കാരത്തിന് ഇഖാമത്ത് കൊടുത്ത ശേഷം നിസ്കരിച്ചു കൊണ്ടിരിക്കുന്ന ഒരാളുടെ അരികിലൂടെ നബി(സ) നടന്നുപോയി. എനിക്കറിയാത്ത എന്തോ കാര്യം നബി(സ) അയാളോട് പറഞ്ഞു. പിരിഞ്ഞു പോകുമ്പോൾ അയാളുടെ ചുറ്റുംകൂടി ഞങ്ങൾ ചോദിച്ചു: നബി(സ) താങ്കളോട് എന്താണ് പറഞ്ഞത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ) എന്നോട് പറഞ്ഞു: "നിങ്ങളിൽ ഒരാൾ ഫജ്ർ നാല് റക്അത്ത് നിസ്കരിച്ചേക്കാം." (ബു,മു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَالِكِ بْنِ بُحَيْنَةَ', 'അബ്ദുല്ലാഹിബ്നു മാലികിബ്നു ബുജൈന(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَبْد الله بن عمرو رَضِيَ اللهُ عَنْهُمَا قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَكُنْ – فِي رِوَايَةِ: يَا عَبْدَ الله – مِثْلَ فُلَانٍ، كَانَ يَقُومُ اللَّيْلَ فَتَرَكَ قِيَامَ اللَّيْلِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ഓ അബ്ദുല്ലാ, രാത്രിയിൽ നിസ്കരിച്ചുകൊണ്ടിരിക്കുകയും ശേഷം ആ പതിവ് ഒഴിവാക്കുകയും ചെയ്തവനെപ്പോലെ നീ ആകരുത്." (ന)', 'عَبْد الله بن عمرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَوْصَانِي خَلِيلِي بِثَلَاثٍ، لَا أَدَعُهُنَّ حَتَّى أَمُوتَ: صَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَصَلَاةِ الضُّحَى، وَنَوْمٍ عَلَى وِتْرٍ. (ق,ن)', 'അബൂഹുറൈറ(റ): എന്റെ ഉറ്റ സ്നേഹിതൻ എന്നോട് മൂന്ന് കാര്യങ്ങൾ നിർദ്ദശിച്ചു. ആ കാര്യങ്ങൾ ഞാൻ മരണംവരെ ഒഴിവാക്കുകയില്ല: എല്ലാ മാസവും മൂന്ന് ദിവസം നോമ്പ് നോൽക്കൽ, ളുഹാ നിസ്കാരം, വിത്ർ നിസ്കാരത്തോടു കൂടിയുള്ള ഉറക്കം എന്നിവയാണ് ആ മൂന്ന് കാര്യങ്ങൾ. (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا صَلَاةَ بَعْدَ الْفَجْرِ إِلَّا سَجْدَتَيْنِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഫജ്ർ വെളിവായ ശേഷം രണ്ട് റക്അത്ത് ഒഴികെ മറ്റു നിസ്കാരമില്ല." (തു)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ ثَابَرَ عَلَى اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي الْيَوْمِ وَاللَّيْلَةِ، دَخَلَ الْجَنَّةَ، وَفِي رِوَايَةٍ: بَنَى اللهُ عَزَّ وَجَلَّ لَهُ بَيْتًا فِي الْجَنَّةِ: أَرْبَعًا قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا، وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ، وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ، وَرَكْعَتَيْنِ قَبْلَ الْفَجْرِ". (ت,ن,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ദിവസേന പന്ത്രണ്ട് റക്അത്ത് നിസ്കരിക്കുന്നവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "അല്ലാഹു അവന് സ്വർഗ്ഗത്തിൽ ഒരു മാളിക നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്. അവ ഇപ്രകാരമാണ്: ളുഹ്റിനു മുമ്പ് നാലു റക്അത്തും, ളുഹ്റ്, മഗ്രിബ്, ഇശാഅ് എന്നിവക്കു ശേഷം ഈരണ്ടു റക്അത്തു വീതവും, സുബ്ഹിക്ക് മുമ്പ് രണ്ട് റക്അത്തും." (തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=57), 1, 'وَفِي رِوَايَةٍ: بَنَى اللهُ عَزَّ وَجَلَّ لَهُ بَيْتًا فِي الْجَنَّةِ: أَرْبَعًا قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا، وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ، وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ، وَرَكْعَتَيْنِ قَبْلَ الْفَجْرِ". (ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "അല്ലാഹു അവന് സ്വർഗ്ഗത്തിൽ ഒരു മാളിക നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്. അവ ഇപ്രകാരമാണ്: ളുഹ്റിനു മുമ്പ് നാലു റക്അത്തും, ളുഹ്റ്, മഗ്രിബ്, ഇശാഅ് എന്നിവക്കു ശേഷം ഈരണ്ടു റക്അത്തു വീതവും, സുബ്ഹിക്ക് മുമ്പ് രണ്ട് റക്അത്തും." (തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ جُرَيْجٍ قَالَ: قُلْتُ لِعَطَاءٍ: بَلَغَنِي أَنَّكَ تَرْكَعُ قَبْلَ الْجُمُعَةِ اثْنَتَيْ عَشْرَةَ رَكْعَةً، مَا بَلَغَكَ فِي ذَلِكَ؟ قَالَ: أُخْبِرْتُ أَنَّ أُمَّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا حَدَّثَتْ عَنْبَسَةَ بْنَ أَبِي سُفْيَانَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَكَعَ اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي الْيَوْمِ وَاللَّيْلَةِ – سِوَى الْمَكْتُوبَةِ – بَنَى اللهُ عَزَّ وَجَلَّ لَهُ بَيْتًا فِي الْجَنَّةِ ". (ن)', 'ഇബ്നു ജുറൈജ്(റ): ഞാൻ അത്വാഇനോട് ചോദിച്ചു: താങ്കൾ ജുമുഅക്കു മുമ്പ് പന്ത്രണ്ട് റക്അത്തുകൾ നിസ്കരിക്കുന്നതായി എനിക്ക് വിവരം ലഭിച്ചു. ആ വിഷയത്തിൽ താങ്കൾക്ക് എന്തെങ്കിലും വിവരം ലഭിച്ചുവോ? അദ്ദേഹം പറഞ്ഞു: അൻബസതുബ്നു അബൂസുഫ്യാനോട് ഉമ്മുഹബീബ(റ) പറഞ്ഞതായി എനിക്ക് വിവരം ലഭിച്ചു. നബി(സ) പറഞ്ഞു: "ഒരാൾ ദിവസേന ഫർളുകൾ ഒഴികെ പന്ത്രണ്ട് റക്അത്തുകൾ നിർവ്വഹിച്ചാൽ അല്ലാഹു അവന് സ്വർഗ്ഗീയ ലോകത്ത് ഒരു ഭവനം പണിതു കൊടുക്കും." (ന)', 'ابْنِ جُرَيْجٍ قَالَ', 'ഇബ്നു ജുറൈജ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ يَعْلَى بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ الطَّائِفَ، فَدَخَلْتُ عَلَى عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ وَهُوَ بِالْمَوْتِ، فَرَأَيْتُ مِنْهُ جَزَعًا، فَقُلْتُ: إِنَّكَ عَلَى خَيْرٍ؟ فَقَالَ: أَخْبَرَتْنِي أُخْتِي أُمُّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَلَّى ثِنْتَيْ عَشْرَةَ رَكْعَةً بِالنَّهَارِ أَوْ بِاللَّيْلِ، بَنَى اللهُ عَزَّ وَجَلَّ لَهُ بَيْتًا فِي الْجَنَّةِ". (ن)', 'യഅ്ലബ്നു ഉമയ്യത്ത്(റ): ഞാൻ ''ത്വാഇഫി''ൽ വന്ന് മരണാസന്നനായ അൻബസത്തുബ്നു അബൂസുഫ്യാന്റെ അടുത്ത് ചെന്നു. അദ്ദേഹത്തിൽ ഭീതി കണ്ടപ്പോൾ ഞാൻ ചോദിച്ചു: നിങ്ങൾ നന്മയിലല്ലേ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ സഹോദരി ഉമ്മുഹബീബ(റ) എന്നോട് പറഞ്ഞു: നബി(സ) പറഞ്ഞിരിക്കുന്നു: "രാപ്പകലിലായി പന്ത്രണ്ട് റക്അത്തുകൾ നിർവ്വഹിക്കുന്ന ഒരാൾക്ക് അല്ലാഹു സ്വർഗ്ഗീയ ലോകത്ത് ഒരു ഭവനം പണിതു കൊടുക്കും." (ന)', 'يَعْلَى بْنِ أُمَيَّةَ', 'യഅ്ലബ്നു ഉമയ്യത്ത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 533, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ التَّطَوُّعِ، فَقَالَتْ: كَانَ يُصَلِّي قَبْلَ الظُّهْرِ أَرْبَعًا فِي بَيْتِي، ثُمَّ يَخْرُجُ فَيُصَلِّي بِالنَّاسِ، ثُمَّ يَرْجِعُ إِلَى بَيْتِي فَيُصَلِّي رَكْعَتَيْنِ، وَكَانَ يُصَلِّي بِالنَّاسِ الْمَغْرِبَ، ثُمَّ يَرْجِعُ إِلَى بَيْتِي فَيُصَلِّي رَكْعَتَيْنِ، وَكَانَ يُصَلِّي بِهِمُ الْعِشَاءَ، ثُمَّ يَدْخُلُ بَيْتِي فَيُصَلِّي رَكْعَتَيْنِ، وَكَانَ يُصَلِّي مِنَ اللَّيْلِ تِسْعَ رَكَعَاتٍ فِيهِنَّ الْوِتْرُ، وَكَانَ يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا، وَلَيْلًا طَوِيلًا جَالِسًا، فَإِذَا قَرَأَ وَهُوَ قَائِمٌ رَكَعَ وَسَجَدَ وَهُوَ قَائِمٌ، وَإِذَا قَرَأَ وَهُوَ قَاعِدٌ رَكَعَ وَسَجَدَ وَهُوَ قَاعِدٌ، وَكَانَ إِذَا طَلَعَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ، ثُمَّ يَخْرُجُ فَيُصَلِّي بِالنَّاسِ صَلَاةَ الْفَجْرِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ)യുടെ സുന്നത്ത് നിസ്കാരങ്ങളെക്കുറിച്ച് അവരോട് ചോദിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: നബി(സ) ളുഹ്റിനു മുമ്പ് എന്റെ വീട്ടിൽ വെച്ച് നാല് റക്അത്ത് നിസ്കരിക്കുകയും പിന്നീട് പള്ളിയിലേക്കു പോയി ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. പിന്നീട് വീട്ടിലേക്ക് മടങ്ങി വന്ന് രണ്ട് റക്അത്തും നിസ്കരിച്ചിരുന്നു. ജനങ്ങൾക്ക് ഇമാമായി മഗ്രിബ് നിസ്കരിക്കുകയും എന്റെ വീട്ടിൽ മടങ്ങിവന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്തിരുന്നു. തുടർന്ന് ജനങ്ങൾക്ക് ഇമാമായി ഇശാഅ് നിസ്കരിക്കുകയും വീട്ടിൽ മടങ്ങിവന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്തിരുന്നു. രാത്രിയിൽ വിത്ർ ഉൾപ്പടെ ഒമ്പത് റക്അത്തുകൾ നിർവ്വഹിച്ചിരുന്നു. രാത്രി ദീർഘനേരം നിന്നും ഇരുന്നും നിസ്കരിക്കാറുണ്ടായിരുന്നു. ഖുർആൻ പാരായണം നിന്ന് നിർവ്വഹിക്കുകയാണെങ്കിൽ നിർത്തത്തിൽ നിന്നും തന്നെ റുകൂഇലേക്കും സുജൂദിലേക്കും പോകും. നിന്നുകൊണ്ട് ഖുർആൻ പാരായണം ചെയ്യുകയാണെങ്കിൽ നിർത്തത്തിൽ തന്നെ സുജൂദിലേക്കും റുകൂഇലേക്കും പോകും. ഖുർആൻ പാരായണം ഇരുന്ന് നിർവ്വഹിക്കുകയാണെങ്കിൽ ഇരുത്തത്തിൽ തന്നെ സുജൂദിലേക്കും റുകൂഇലേക്കും പോകും. ശേഷം (പ്രഭാതം പുലർന്നാൽ) രണ്ടു റക്അത്ത് നിസ്കരിക്കും. ശേഷം പള്ളിയിലേക്ക് പുറപ്പെടുകയും ജനങ്ങൾക്ക് ഇമാമായി കൊണ്ട് സുബ്ഹ് നിസ്കരിക്കുകയും ചെയ്യുമായിരുന്നു. (മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي قَبْلَ الظُّهْرِ رَكْعَتَيْنِ، وَبَعْدَهَا رَكْعَتَيْنِ، وَبَعْدَ الْمَغْرِبِ رَكْعَتَيْنِ فِي بَيْتِهِ، وَبَعْدَ صَلَاةِ الْعِشَاءِ رَكْعَتَيْنِ، وَكَانَ لَا يُصَلِّي بَعْدَ الْجُمُعَةِ حَتَّى يَنْصَرِفَ، فَيُصَلِّي رَكْعَتَيْنِ. (ق,د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) ളുഹ്റിനു മുമ്പ് രണ്ടു റക്അത്തും, ശേഷം രണ്ടു റക്അത്തും, മഗ്രിബിന് ശേഷം വീട്ടിൽ വെച്ച് രണ്ടു റക്അത്തും, ഇശാക്ക് ശേഷം രണ്ടു റക്അത്തും, നിസ്കരിച്ചിരുന്നു. ജുമുഅക്കു ശേഷം അവിടെ നിന്നും പിരിഞ്ഞുപോകുന്നതു വരെ നിസ്കരിച്ചിരുന്നില്ല. മടങ്ങിപ്പോയശേഷം (വീട്ടിലെത്തിയാൽ) രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദന']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أُمِّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اثْنَتَا عَشْرَةَ رَكْعَةً، مَنْ صَلَّاهُنَّ بَنَى اللهُ لَهُ بَيْتًا فِي الْجَنَّةِ: أَرْبَعَ رَكَعَاتٍ قَبْلَ الظُّهْرِ، وَرَكْعَتَيْنِ بَعْدَ الظُّهْرِ، وَرَكْعَتَيْنِ قَبْلَ الْعَصْرِ، وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ، وَرَكْعَتَيْنِ قَبْلَ صَلَاةِ الصُّبْحِ". وَفِي رِوَايَةٍ: "مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً بَنَى اللهُ لَهُ بَيْتًا فِي الْجَنَّةِ: أَرْبَعًا قَبْلَ الظُّهْرِ، وَاثْنَتَيْنِ بَعْدَهَا، وَاثْنَتَيْنِ قَبْلَ الْعَصْرِ، وَاثْنَتَيْنِ بَعْدَ الْمَغْرِبِ، وَاثْنَتَيْنِ قَبْلَ الصُّبْحِ". (ن)', 'ഉമ്മുഹബീബ ബിൻത് അബൂസുഫ്യാൻ(റ): നബി(സ) പറഞ്ഞു: "ളുഹ്റിനു മുമ്പ് നാലും, ശേഷം രണ്ടും, അസ്വറിനു മുമ്പ് രണ്ടും മഗ്രിബിനു ശേഷം രണ്ടും, സുബ്ഹ്ന് മുമ്പ് രണ്ടും ഉൾപ്പെടുന്ന പന്ത്രണ്ട് റക്അത്ത് നിസ്കാരം രാപകലുകളിലായി നിസ്കരിക്കുന്നവന് അല്ലാഹു സ്വർഗ്ഗീയ ലോകത്ത് ഒരു ഭവനം പണിതു കൊടുക്കുന്നതാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "ആരെങ്കിലും പന്ത്രണ്ട് റക്അത്ത് നിസ്കരിച്ചാൽ അല്ലാഹു അവന് സ്വർഗ്ഗീയ ലോകത്ത് ഒരു ഭവനം പണിതു കൊടുക്കും. ളുഹ്റിനു മുമ്പ് നാല്, ശേഷം രണ്ട്, അസ്വറിനു മുമ്പ് രണ്ട്, മഗ്രിബിന് ശേഷം രണ്ട്, സുബ്ഹിക്ക് മുമ്പ് രണ്ട് എന്നിങ്ങനെയാണത്." (ന)', 'أُمِّ حَبِيبَةَ', 'ഉമ്മുഹബീബ ബിൻത് അബൂസുഫ്യാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=62), 1, 'وَفِي رِوَايَةٍ: "مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً بَنَى اللهُ لَهُ بَيْتًا فِي الْجَنَّةِ: أَرْبَعًا قَبْلَ الظُّهْرِ، وَاثْنَتَيْنِ بَعْدَهَا، وَاثْنَتَيْنِ قَبْلَ الْعَصْرِ، وَاثْنَتَيْنِ بَعْدَ الْمَغْرِبِ، وَاثْنَتَيْنِ قَبْلَ الصُّبْحِ". (ن)', 'മറ്റൊരു നിവേദനിൽ: "ആരെങ്കിലും പന്ത്രണ്ട് റക്അത്ത് നിസ്കരിച്ചാൽ അല്ലാഹു അവന് സ്വർഗ്ഗീയ ലോകത്ത് ഒരു ഭവനം പണിതു കൊടുക്കും. ളുഹ്റിനു മുമ്പ് നാല്, ശേഷം രണ്ട്, അസ്വറിനു മുമ്പ് രണ്ട്, മഗ്രിബിന് ശേഷം രണ്ട്, സുബ്ഹിക്ക് മുമ്പ് രണ്ട് എന്നിങ്ങനെയാണത്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلَ الظُّهْرِ سَجْدَتَيْنِ، وَبَعْدَهَا سَجْدَتَيْنِ، وَبَعْدَ الْمَغْرِبِ سَجْدَتَيْنِ، وَبَعْدَ الْعِشَاءِ سَجْدَتَيْنِ، وَبَعْدَ الْجُمُعَةِ سَجْدَتَيْنِ، فَأَمَّا الْمَغْرِبُ وَالْعِشَاءُ وَالْجُمُعَةُ، فَصَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِهِ. (م)', 'ഇബ്നു ഉമർ(റ): ഞാൻ നബി(സ)യോടൊപ്പം ളുഹ്റിനു മുമ്പ് രണ്ടും, ശേഷം രണ്ടും, മഗ്രിബിനു ശേഷം രണ്ടും, ഇശാഇന് ശേഷം രണ്ടും, ജുമുഅക്കു ശേഷം രണ്ടും റക്അത്തുകൾ വീതം നിസ്കരിച്ചു. മഗ്രിബ്, ഇശാ, ജുമുഅഃ എന്നിവ നബി(സ)യോടൊപ്പം അവിടുത്തെ വീട്ടിൽ വെച്ചു ഞാൻ നിസ്കരിച്ചു. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أُمِّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ حَبِيبَهَا أَبَا الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَهَا قَالَ: "مَا مِنْ عَبْدٍ مُؤْمِنٍ يُصَلِّي أَرْبَعَ رَكَعَاتٍ بَعْدَ الظُّهْرِ فَتَمَسَّ وَجْهَهُ النَّارُ أَبَدًا، إِنْ شَاءَ اللهُ عَزَّ وَجَلَّ". (د,ن)', 'ഉമ്മുഹബീബ ബിൻത് അബൂസുഫ്യാൻ(റ): നബി(സ) അവരോട് പറഞ്ഞു: "ളുഹ്റിനു ശേഷം നാല് റക്അത്ത് നിസ്കാരം നിർവ്വഹിക്കുന്ന വിശ്വാസിയായ ഒരടിമയുടെ മുഖത്തെ ഒരിക്കലും നരകം സ്പർശിക്കുകയില്ല. ഇൻശാ അല്ലാഹ്." (ദ,ന)', 'أُمِّ حَبِيبَةَ', 'ഉമ്മുഹബീബ ബിൻത് അബൂസുഫ്യാൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَدَعُ أَرْبَعًا قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ قَبْلَ الْغَدَاةِ. (خ,د,ن)', 'ആഇശ(റ): നബി(സ) ളുഹ്റിനു മുമ്പുള്ള നാല് റക്അത്തും സുബ്ഹിക്കു മുമ്പുള്ള രണ്ട് റക്അത്തും ഉപേക്ഷിക്കാറില്ല. (ബു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ قَابُوسَ، عَنْ أَبِيهِ قَالَ: أَرْسَلَ أَبِي إِلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَيُّ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ أَحَبَّ إِلَيْهِ أَنْ يُوَاظِبَ عَلَيْهَا؟ قَالَتْ: كَانَ يُصَلِّي أَرْبَعًا قَبْلَ الظُّهْرِ، يُطِيلُ فِيهِنَّ الْقِيَامَ، وَيُحْسِنُ فِيهِنَّ الرُّكُوعَ وَالسُّجُودَ. [ز: في إسناده راو مختلف فيه] (جه)', 'ഖാബൂസ്(റ) തന്റെ പിതാവിൽ നിന്ന്: എന്റെ പിതാവ് എന്നെ (ഒരു വിവരമറിയാൻ) ആഇശ(റ)ന്റെ അടുത്തേക്കു പറഞ്ഞയച്ചു. നബി(സ) പതിവാക്കാൻ ഏറ്റവും ഇഷ്ടപ്പെട്ടിരുന്ന നിസ്കാരം ഏതായിരുന്നു? അവർ പറഞ്ഞു: നബി(സ) ളുഹ്റിനു മുമ്പുള്ള നാല് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു, അതിൽ നിർത്തം ദീർഘിപ്പിച്ചു. റുകൂഉം സുജൂദും നന്നായി (ദീർഘമായി) നിർവ്വഹിച്ചിരുന്നു. (ഇതിന്റെ പരമ്പരയിലെ ഒരു റാവിയെക്കുറിച്ച് അഭിപ്രായവ്യത്യാസമുണ്ടെന്ന് ഇബ്നു മാജ പറയുന്നു) (ജ)', 'قَابُوسَ، عَنْ أَبِيهِ قَالَ', 'ഖാബൂസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده راو مختلف فيه', null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي قَبْلَ الظُّهْرِ أَرْبَعًا إِذَا زَالَتِ الشَّمْسُ، لَا يَفْصِلُ بَيْنَهُنَّ بِتَسْلِيمٍ، وَقَالَ: "إِنَّ أَبْوَابَ السَّمَاءِ تُفَتَّحُ إِذَا زَالَتِ الشَّمْسُ". (د,جه)', 'അബൂഅയ്യൂബ്(റ): സൂര്യൻ മദ്ധ്യത്തിൽ നിന്ന് നീങ്ങിയാൽ നബി(സ) ളുഹ്റിനു മുമ്പ് നാല് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. അവക്കിടയിൽ സലാം കൊണ്ട് വേർതിരിക്കുകയില്ല. ശേഷം നബി(സ) പറഞ്ഞു: "സൂര്യൻ (മദ്ധ്യത്തിൽ നിന്ന്) നീങ്ങിയാൽ ആകാശ വാതിലുകൾ തുറക്കപ്പെടുന്നതാണ്." (ദ,ജ)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا فَاتَتْهُ الْأَرْبَعُ قَبْلَ الظُّهْرِ صَلَّاهَا بَعْدَ الرَّكْعَتَيْنِ بَعْدَ الظُّهْرِ. (ت,جه)', 'ആഇശ(റ): നബി(സ)ക്ക് ളുഹ്റിനു മുമ്പുള്ള നാല് റക്അത്തുകൾ നഷ്ടപ്പെട്ടാൽ ശേഷമുള്ള രണ്ട് റക്അത്തുകൾക്കു ശേഷം അവ നിർവ്വഹിക്കുമായിരുന്നു. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَبْدِ اللهِ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: أَرْسَلَ مُعَاوِيَةُ رَضِيَ اللهُ عَنْهُ إِلَى أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، فَانْطَلَقْتُ مَعَ الرَّسُولِ، فَسَأَلَ أُمَّ سَلَمَةَ، فَقَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَمَا هُوَ يَتَوَضَّأُ فِي بَيْتِي لِلظُّهْرِ، وَكَانَ قَدْ بَعَثَ سَاعِيًا، وَكَثُرَ عِنْدَهُ الْمُهَاجِرُونَ، وَقَدْ أَهَمَّهُ شَأْنُهُمْ، إِذْ ضُرِبَ الْبَابُ، فَخَرَجَ إِلَيْهِ، فَصَلَّى الظُّهْرَ، ثُمَّ جَلَسَ يَقْسِمُ مَا جَاءَ بِهِ، قَالَتْ: فَلَمْ يَزَلْ كَذَلِكَ حَتَّى الْعَصْرِ، ثُمَّ دَخَلَ مَنْزِلِي فَصَلَّى رَكْعَتَيْنِ، ثُمَّ قَالَ: "شَغَلَنِي أَمْرُ السَّاعِي أَنْ أُصَلِّيَهُمَا بَعْدَ الظُّهْرِ، فَصَلَّيْتُهُمَا بَعْدَ الْعَصْرِ". [ز: في إسناده مدلس عنعنه] (جه)', 'അബ്ദുല്ലാഹിബ്നു ഹാരിസ്(റ): മുആവിയ(റ) ഉമ്മുസലമ(റ)യിലേക്ക് ഒരു ദൂതനെ അയച്ചു. ആ ദൂതനോടൊപ്പം ഞാനും പോയി. അയാൾ ഉമ്മുസലമയോട് (മതാനുഷ്ഠാനങ്ങളെപ്പറ്റി) ചോദിച്ചു. അവർ പറഞ്ഞു: നബി(സ) സകാത്ത് പിരിച്ചെടുക്കാൻ ആളെ നിയോഗിച്ചിരിക്കെ എന്റെ വീട്ടിൽവെച്ച് ളുഹ്റിന് വുദു ചെയ്തു കൊണ്ടിരിക്കുകയായിരുന്നു. അന്നേരം തിരുമേനി(സ)യുടെ അടുത്താകട്ടെ ധാരാളം മുഹാജിറുകൾ ഒരുമിച്ച് കൂടിയിട്ടുണ്ട്. അവരുടെ കാര്യം തിരുമേനി(സ)യെ വിഷമത്തിലാക്കുകയും ചെയ്തിട്ടുണ്ട്. അപ്പോഴാണ് വാതിലിൽ മുട്ടുന്നതായി കേട്ടത്. നബി(സ) അവരിലേക്കു ചെന്ന് ളുഹ്ർ നിസ്കരിച്ചു. പിന്നെ കൊണ്ടുവന്നത് (സകാത്തിന്റെ ധനം) വിഹിതം വെക്കാനായി ഇരുന്നു. അസ്ർ വരെ തിരുമേനി(സ) അതു (വിഹിതം വെക്കൽ) തുടർന്നു. പിന്നെ എന്റെ വീട്ടിൽ വന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. നബി(സ) പറഞ്ഞു: "ളുഹ്റിനു ശേഷമുള്ള ഈ രണ്ട് റക്അത്ത് നിസ്കരിക്കുന്നതിൽ നിന്ന് സകാത്ത് പിരിക്കാൻ നിയോഗിക്കപ്പെട്ടവന്റെ കാര്യം എന്നെ വ്യാപൃതനാക്കി. അതിനാൽ ഞാൻ അവ അസ്റിനു ശേഷം നിസ്കരിച്ചു." (ഇതിന്റെ പരമ്പരിയിൽ ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുണ്ടെന്ന് ഇബ്നു മാജ പറയുന്നു) (ജ)', 'عَبْدِ اللهِ بْنِ الْحَارِثِ', 'അബ്ദുല്ലാഹിബ്നു ഹാരിസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مدلس عنعنه', null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا. حَدِيثٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നു ഉമർ(റ): ഞാൻ നബി(സ)യോടൊപ്പം ളുഹ്റിനു മുമ്പ് രണ്ട് റക്അത്തും ശേഷം രണ്ട് റക്അത്തും നിസ്കരിച്ചു. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا لَمْ يُصَلِّ أَرْبَعًا قَبْلَ الظُّهْرِ صَلَّاهُنَّ بَعْدَهُ. حَسَنٌ غَرِيبٌ. (ت)', 'ആഇശ(റ): നബി(സ) ളുഹ്റിനു മുമ്പ് നാലു റക്അത്ത് നിസ്കരിച്ചിട്ടില്ലെങ്കിൽ ളുഹ്റിനു ശേഷം അത് നിസ്കരിക്കുമായിരുന്നു. ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي قَبْلَ الظُّهْرِ أَرْبَعًا وَبَعْدَهَا رَكْعَتَيْنِ. حَسَنٌ. (ت)', 'അലി(റ): നബി(സ) ളുഹ്റിനു മുമ്പ് നാല് റക്അത്തും ശേഷം രണ്ട് റക്അത്തും നിസ്കരിക്കുമായിരുന്നു. ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു. (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ أُخْتِي أُمَّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا – زَوْجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – تَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ حَافَظَ عَلَى أَرْبَعِ رَكَعَاتٍ قَبْلَ الظُّهْرِ، وَأَرْبَعٍ بَعْدَهَا حَرَّمَهُ اللهُ عَلَى النَّارِ". حَسَنٌ صَحِيحٌ غَرِيبٌ. (د,ت,ن,جه)', 'അൻബസതുബ്നു അബീസുഫ്യാൻ(റ): എന്റെ സഹോദരി (നബി(സ)യുടെ ഭാര്യ) ഉമ്മു ഹബ്ബീബ(റ) പറയുന്നത് ഞാൻ കേട്ടു: അവർ പറയുന്നു: നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ളുഹ്റിനു മുമ്പുള്ള നാലും, ശേഷമുള്ള നാലും റക്അത്തുകൾ പതിവാക്കിയാൽ അല്ലാഹു അവനെ നരകത്തിനുമേൽ നിഷിദ്ധമാക്കും." (ഹദീസ് ഹസനും സഹീഹും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു,ന,ജ)', 'عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ', 'അൻബസതുബ്നു അബീസുഫ്യാൻ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ صَلَاتَيْنِ: عَنِ الصَّلَاةِ بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ، وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ. (ق,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) രണ്ട് നിസ്കാരങ്ങൾ നിരോധിച്ചിരിക്കുന്നു; സുബ്ഹിക്കു ശേഷം സൂര്യൻ ഉദിക്കുന്നതു വരെയുള്ള നിസ്കാരവും, അസ്ർ നിസ്കാര ശേഷം സൂര്യൻ അസ്തമിക്കുന്നതു വരെയുള്ള നിസ്കാരവുമാണവ. (ബു,മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ، فِيهِمْ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، وَأَرْضَاهُمْ عِنْدِي عُمَرُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا صَلَاةَ بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ، وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ". (ق,د,ت,ن,جه)', 'ഇബ്നു അബ്ബാസ്(റ): എനിക്കിഷ്ടപ്പെട്ട കുറെയാളുകൾ എന്റടുക്കൽ ഇപ്രകാരം സാക്ഷ്യം പറഞ്ഞു: അക്കൂട്ടത്തിൽ ഉമർ(റ)വും ഉണ്ടായിരുന്നു. അവരിൽ എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ടത് ഉമർ(റ) ആയിരുന്നു. നബി(സ) പറഞ്ഞു: "സുബ്ഹിക്കു ശേഷം സൂര്യൻ ഉദിക്കുന്നതു വരെയും അസ്റിനു ശേഷം സൂര്യൻ അസ്തമിക്കുന്നതു വരെയും നിസ്കാരമില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ كُرَيْبٍ مَوْلَى ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عَبْدَ اللهِ بْنَ عَبَّاسٍ وَعَبْدَ الرَّحْمَنِ بْنَ أَزْهَرَ وَالْمِسْوَرَ بْنَ مَخْرَمَةَ – رَضِيَ اللهُ عَنْهُمْ – أَرْسَلُوهُ إِلَى عَائِشَةَ – رَضِيَ اللهُ عَنْهَا – فَقَالُوا: اقْرَأْ عَلَيْهَا السَّلَامَ مِنَّا جَمِيعًا، وَسَلْهَا عَنِ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ، وَقُلْ: إِنَّا أُخْبِرْنَا أَنَّكِ تُصَلِّينَهُمَا، وَقَدْ بَلَغَنَا أَنَّ رَسُو لَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهُمَا فَدَخَلْتُ عَلَيْهَا فَبَلَّغْتُهَا مَا أَرْسَلُونِي بِهِ، فَقَالَتْ: سَلْ أُمَّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، فَخَرَجْتُ إِلَيْهِمْ فَأَخْبَرْتُهُمْ بِقَوْلِهَا، فَرَدُّونِي إِلَى أُمِّ سَلَمَةَ بِمِثْلِ مَا أَرْسَلُونِي بِهِ إِلَى عَائِشَةَ، فَقَالَتْ أُمُّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْهُمَا، ثُمَّ رَأَيْتُهُ يُصَلِّيهِمَا، أَمَّا حِينَ صَلَّاهُمَا فَإِنَّهُ صَلَّى الْعَصْرَ، ثُمَّ دَخَلَ وَعِنْدِي نِسْوَةٌ مِنْ بَنِي حَرَامٍ مِنَ الْأَنْصَارِ فَصَلَّاهُمَا، فَأَرْسَلْتُ إِلَيْهِ الْجَارِيَةَ، فَقُلْتُ: قُومِي بِجَنْبِهِ فَقُولِي لَهُ: تَقُولُ أُمُّ سَلَمَةَ: يَا رَسُولَ اللهِ، أَسْمَعُكَ تَنْهَى عَنْ هَاتَيْنِ الرَّكْعَتَيْنِ، وَأَرَاكَ تُصَلِّيهِمَا؟ فَإِنْ أَشَارَ بِيَدِهِ فَاسْتَأْخِرِي عَنْهُ. قَالَتْ: فَفَعَلَتِ الْجَارِيَةُ، فَأَشَارَ بِيَدِهِ، فَاسْتَأْخَرَتْ عَنْهُ، فَلَمَّا انْصَرَفَ قَالَ: "يَا بِنْتَ أَبِي أُمَيَّةَ، سَأَلْتِ عَنِ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ، إِنَّهُ أَتَانِي نَاسٌ مِنْ عَبْدِ الْقَيْسِ بِالْإِسْلَامِ مِنْ قَوْمِهِمْ، فَشَغَلُونِي عَنِ الرَّكْعَتَيْنِ اللَّتَيْنِ بَعْدَ الظُّهْرِ، فَهُمَا هَاتَانِ". (ق,د)', 'കുറൈബ്(റ): അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ), അബ്ദുർറഹ്മാനുബ്നു അസ്ഹർ(റ), മിസ്വറുബ്നു മഖ്റമ(റ) എന്നിവർ എന്നെ ആഇശ(റ)യുടെ അടുത്തേക്ക് പറഞ്ഞയച്ചു. അവർ പറഞ്ഞു: മഹതിക്ക് ഞങ്ങളുടെയെല്ലാം സലാം അറിയിക്കുക. അസ്ർ നിസ്കാരത്തെ തുടർന്നുള്ള സുന്നത്ത് നിസ്കാരത്തെക്കുറിച്ച് അവരോട് ചോദിക്കുക. നബി(സ) അവ നിരോധിച്ചതായി ഞങ്ങൾ അറിഞ്ഞിട്ടുണ്ടെന്നും, പക്ഷേ, അത് അവർ (ആഇശ(റ)) നിസ്കരിക്കുന്നതായി ഞങ്ങൾ അറിഞ്ഞിട്ടുണ്ടെന്നും അവരോട് പറയുക. അങ്ങനെ ഞാൻ ആഇശ(റ)യുടെ അടുത്തെത്തി തന്നെ അയച്ച കാര്യം പറഞ്ഞു. അപ്പോൾ അവർ പറഞ്ഞു: നിങ്ങൾ അതിനെപ്പറ്റി ഉമ്മുസലമ(റ)യോട് ചോദിക്കുക. ഞാൻ അവരുടെ (മൂവർ സംഘം) അടുത്തുചെന്ന് ആഇശ(റ)യുടെ പ്രതികരണം അറിയിച്ചപ്പോൾ ആഇശ(റ)യുടെ അടുത്തേക്ക് പറഞ്ഞയച്ചതുപോലെ ഉമ്മുസലമ(റ)യുടെ അടുക്കലേക്കും എന്നെ പറഞ്ഞയച്ചു. ഉമ്മുസലമ(റ) പറഞ്ഞു: നബി(സ) അസ്ർ നിസ്കാരത്തിനു ശേഷമുള്ള സുന്നത്ത് നിസ്കാരം നിരോധിക്കുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. പിന്നെ നബി(സ) അത് നിർവ്വഹിക്കുന്നതും ഞാൻ കണ്ടിട്ടുണ്ട്. തീർച്ചയായും നബി(സ) അത് നിസ്കരിക്കുമ്പോൾ അസ്ർ നിസ്കരിച്ചിട്ടുണ്ടായിരുന്നു. പിന്നീട് നബി(സ) കടന്നുവന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. എന്റെ അടുക്കൽ അൻസ്വാരികളിൽപെട്ട ''ബനൂ ഹറാം'' ഗോത്രത്തിലെ ഒരുകൂട്ടം സ്ത്രീകളുണ്ടായിരുന്നു. ഞാൻ നബി(സ)യുടെ അടുത്തേക്ക് ഒരു വേലക്കാരിയെ പറഞ്ഞയച്ചു. അവളോട് പറഞ്ഞു: നീ നബി(സ)യുടെ അടുത്തുചെന്ന് ഇപ്രകാരം പറയുക: അല്ലാഹുവിന്റെ ദൂതരെ, ഈ (അസ്റിനു ശേഷമുള്ള) രണ്ട് റക്അത്ത് നിസ്കരിക്കരുതെന്ന് അങ്ങ് പറഞ്ഞത് കേട്ടതായും, ഇപ്പോൾ അങ്ങുതന്നെ അവ നിർവ്വഹിച്ചതായും ഉമ്മുസലമ പറയുന്നു: അപ്പോൾ നബി(സ) കൈ കൊണ്ട് ആംഗ്യം കാണിച്ചാൽ നീ അവിടെ നിന്ന് മാറിനിൽക്കുക. വേലക്കാരി അപ്രകാരം ചെയ്തു. നബി(സ) കൈകൊണ്ട് ആംഗ്യം കാണിച്ചു. അവൾ മാറിനിന്നു. ശേഷം വിരമിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഓ അബൂഉമയ്യയുടെ മകളേ, നീ അസറിനു ശേഷമുള്ള രണ്ട് റക്അത്തിനെക്കുറിച്ച് ചോദിച്ചുവല്ലോ, അബദുൽഖൈസ് ഗോത്രത്തിലെ ഒരുവിഭാഗം ആളുകൾ ഇസ്ലാം ആശ്ലേഷിക്കാനായി എന്റെ അടുക്കൽ വന്നു. അതു കൊണ്ട് ളുഹ്റിനു ശേഷമുള്ള രണ്ട് റക്അത്ത് സുന്നത്ത് നിസ്കരിക്കാൻ സാധിച്ചില്ല. അതാണ് ഇത്." (ബു,മു,ദ)', 'كُرَيْبٍ مَوْلَى ابْنِ عَبَّاسٍ', 'കുറൈബ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 537, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الصَّلَاةِ بَعْدَ الْعَصْرِ إِلَّا وَالشَّمْسُ مُرْتَفِعَةٌ. (د,ن)', 'അലി(റ): അസറിന്നു ശേഷമുള്ള സുന്നത്ത് നിസ്കാരത്തെ നബി(സ) നിരോധിച്ചു. സൂര്യൻ ഉയർന്നു നിൽക്കുന്ന സമയത്ത് ഒഴികെ. (ദ,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي إِثْرِ كُلِّ صَلَاةٍ مَكْتُوبَةٍ رَكْعَتَيْنِ إِلَّا الْفَجْرَ وَالْعَصْرَ. (د)', 'അലി(റ): സുബ്ഹ്, അസ്ർ എന്നീ നിസ്കാരങ്ങൾ ഒഴികെയുള്ള എല്ലാ നിർബന്ധ നിസ്കാരങ്ങൾക്കും ശേഷം നബി(സ) രണ്ടു റക്അത്തുകൾ വീതം നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي أُمَامَةَ، عَنْ عَمْرِو ابْنِ عَبْسَةَ السُّلَمِيِّ – رَضِيَ اللهُ عَنْهُمَا – أَنَّهُ قَالَ: قُلْتُ: يَا رَسُو لَ اللهِ، أَيُّ اللَّيْلِ أَسْمَعُ؟ قَالَ: "جَوْفُ اللَّيْلِ الْآخِرُ، فَصَلِّ مَا شِئْتَ، فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَكْتُوبَةٌ حَتَّى تُصَلِّيَ الصُّبْحَ، ثُمَّ أَقْصِرْ حَتَّى تَطْلُعَ الشَّمْسُ فَتَرْتَفِعَ قِيسَ رُمْحٍ أَوْ رُمْحَيْنِ، فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَيُصَلِّي لَهَا الْكُفَّارُ. ثُمَّ صَلِّ مَا شِئْتَ، فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَكْتُوبَةٌ حَتَّى يَعْدِلَ الرُّمْحُ ظِلَّهُ، ثُمَّ أَقْصِرْ فَإِنَّ جَهَنَّمَ تُسْجَرُ وَتُفْتَحُ أَبْوَابُهَا، فَإِذَا زَاغَتِ الشَّمْسُ فَصَلِّ مَا شِئْتَ، فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ حَتَّى تُصَلِّيَ الْعَصْرَ، ثُمَّ أَقْصِرْ حَتَّى تَغْرُبَ الشَّمْسُ، فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَيُصَلِّي لَهَا الْكُفَّارُ". (م,د,ت,جه)', 'അംറുബ്നു അബസ(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, രാത്രിയിൽ ഏത് സമയത്താണ് പ്രാർത്ഥനക്ക് കൂടുതൽ ഉത്തരം കിട്ടുക? നബി(സ) പറഞ്ഞു: "അർദ്ധരാത്രിയിലാണ് ലഭിക്കുക, അപ്പോൾ നീ ഉദ്ദേശിക്കുന്നത്ര നിസ്കരിക്കുക. കാരണം ആ നിസ്കാരം സുബ്ഹ് നിസ്കരിക്കുന്നതുവരെ സാക്ഷി നിൽക്കപ്പെടുന്നതും, രേഖപ്പെടുത്തപ്പെടുന്നതുമാണ്. സുബ്ഹ് നിസ്കരിച്ചാൽ നീ നിസ്കാരം നിർത്തുക. സൂര്യൻ ഉദിച്ച് ഒരു കുന്തത്തോളം ഉയരത്തിൽ (ശരാശരി ഇരുപത്തിരണ്ട് മിനുട്ട്), അല്ലെങ്കിൽ രണ്ട് കുന്തത്തോളം ഉയരുന്നതുവരെ. കാരണം അപ്പോൾ സൂര്യൻ ഉദിക്കുന്നത് പിശാചിന്റെ രണ്ട് കൊമ്പുകൾക്കിടയിലൂടെയാണ്. അപ്പോൾ സത്യനിഷേധികൾ സൂര്യനുവേണ്ടി നിസ്കരിക്കുന്നു. പിന്നെ നീ ഉദ്ദേശിച്ചത്ര നിസ്കരിക്കുക. കാരണം, ആ നിസ്കാരം രേഖപ്പെടുത്തപ്പെടുന്നതും സാക്ഷി നിർത്തപ്പെടുന്നതുമാണ്. കുന്തം നിഴലിനോടു സമാനമാകുംവരെ. പിന്നെ നിർത്തുക, കാരണം നരകം കത്തിക്കപ്പെടുകയും, അതിന്റെ വാതിലുകൾ തുറക്കപ്പെടുകയും ചെയ്യും. സൂര്യൻ തെറ്റിയാൽ നീ ഉദ്ദേശിക്കുന്നത്ര നിസ്കരിക്കുക. ആ നിസ്കാരം രേഖപ്പെടുത്തപ്പെടുന്നതും സാക്ഷി നിർത്തപ്പെടുന്നതുമാണ്. അസ്ർ നിസ്കാരശേഷം സൂര്യൻ അസ്തമിക്കുംവരെ നിർത്തുക. കാരണം, ചെകുത്താന്റെ രണ്ട് കൊമ്പുകൾക്കിടയിൽ വെച്ചാണ് അത് അസ്തമിക്കുന്നത്. അവിശ്വാസികൾ അതിന് നിസ്കരിക്കുന്നു." (മു,ദ,തു,ജ)', 'أَبِي أُمَامَةَ، عَنْ عَمْرِو ابْنِ عَبْسَةَ السُّلَمِيِّ –', 'അംറുബ്നു അബസ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 538, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ يَسَارٍ مَوْلَى ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَآنِي ابْنُ عُمَرَ وَأَنَا أُصَلِّي بَعْدَ طُلُوعِ الْفَجْرِ، فَقَالَ: يَا يَسَارُ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَيْنَا وَنَحْنُ نُصَلِّي هَذِهِ الصَّلَاةَ، فَقَالَ: "لِيُبَلِّغْ شَاهِدُكُمْ غَائِبَكُمْ، لَا تُصَلُّوا بَعْدَ الْفَجْرِ إِلَّا سَجْدَتَيْنِ". (د,ت,جه)', 'യസാർ(റ): ഫജ്ർ വെളിവായ ശേഷം ഞാൻ നിസ്കരിച്ചുകൊണ്ടിരിക്കെ ഇബ്നു ഉമർ(റ) എന്നെ കണ്ടു. അദ്ദേഹം പറഞ്ഞു: യസാർ, ഞങ്ങൾ ഈ നിസ്കാരം നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ നബി(സ) ഞങ്ങളിലേക്ക് വന്ന് ഇപ്രകാരം പറഞ്ഞു: "നിങ്ങളിൽ ഇവിടെ സന്നിഹിതരായവർ ഇവിടെ ഹാജറാകാത്തവർക്ക് എത്തിച്ചു കൊടുക്കുക: ഫജ്ർ ആയശേഷം രണ്ട് നിസ്കാര(സുബ്ഹ്, സുബ്ഹിക്കു മുമ്പുള്ള സുന്നത്ത്)മല്ലാതെ നിസ്കരിക്കരുത്." (ദ,തു,ജ)', 'يَسَارٍ مَوْلَى ابْنِ عُمَرَ', 'യസാർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: مَا مِنْ يَوْمٍ يَأْتِي عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَّا صَلَّى بَعْدَ الْعَصْرِ رَكْعَتَيْنِ. (ق,د,ن)', 'ആഇശ(റ): നബി(സ) ഒറ്റ ദിവസവും അസ്വറിനു ശേഷം രണ്ട് റക്അത്ത് നിസ്കരിക്കാതിരുന്നിട്ടില്ല. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بَعْدَ الْعَصْرِ وَيَنْهَى عَنْهَا وَيُوَاصِلُ وَيَنْهَى عَنِ الْوِصَالِ. (د)', 'ആഇശ(റ): നബി(സ) അസ്റിനുശേഷം നിസ്കരിക്കുകയും, ഞങ്ങൾ (മറ്റുള്ളവർ) അപ്രകാരം നിസ്കരിക്കുന്നത് വിലക്കുകയും, തുർച്ചയായി നോമ്പനുഷ്ടിക്കുകയും മറ്റുള്ളവർ അപ്രകാരം ചെയ്യുന്നത് വിലക്കുകയും ചെയ്തിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي قَبْلَ الْعَصْرِ أَرْبَعَ رَكَعَاتٍ، يَفْصِلُ بَيْنَهُنَّ بِالتَّسْلِيمِ عَلَى الْمَلَائِكَةِ الْمُقَرَّبِينَ، وَمَنْ تَبِعَهُمْ مِنَ الْمُسْلِمِينَ وَالْمُؤْمِنِينَ. (ت,ن)', 'അലി(റ): നബി(സ) അസ്റിനു മുമ്പ് നാല് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. അവക്കിടയിൽ അല്ലാഹുവിന്റെ സാമീപ്യം സിദ്ധിച്ച മലക്കുകളുടെയും, അവരെ പിൻപറ്റിയ വിശ്വാസികളുടെയും മേൽ സലാം ചൊല്ലി വേർപിരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (തു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَانَ يُصَلِّي قَبْلَ الْعَصْرِ رَكْعَتَيْنِ. (د)', 'അലി(റ): നബി(സ) അസ്വറിനു മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَحِمَ اللهُ امْرَأً صَلَّى قَبْلَ الْعَصْرِ أَرْبَعًا". غَرِيبٌ حَسَنٌ. (د,ت)', 'ഇബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "അസ്ർ നിസ്കാരത്തിനു മുമ്പ് നാല് റക്അത്ത് നിസ്കരിക്കുന്ന ഒരാൾക്ക് അല്ലാഹു കരുണ ചെയ്യട്ടെ." (ഹദീസ് ഗരീബും ഹസനുമാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَبْدِ اللهِ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا قَبْلَ الْمَغْرِبِ رَكْعَتَيْنِ". ثُمَّ قَالَ: "صَلُّوا قَبْلَ الْمَغْرِبِ رَكْعَتَيْنِ لِمَنْ شَاءَ". خَشْيَةَ أَنْ يَتَّخِذَهَا النَّاسُ سُنَّةً. (خ,د)', 'അബ്ദുർറഹ്മാനുബ്നുൽ മുസനി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മഗ്രിബിനു മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിക്കുക." ജനങ്ങൾ അതൊരു നിത്യനടപടിയായി കണക്കാക്കുമോ എന്ന് ഭയന്നതുകൊണ്ട് പിന്നീട് നബി(സ) ഇങ്ങനെ പറഞ്ഞു: "നിങ്ങൾ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ മഗ്രിബിനു മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിക്കുക." (ബു,ദ)', 'عَبْدِ اللهِ الْمُزَنِيِّ', 'അബ്ദുർറഹ്മാനുബ്നുൽ മുസനി(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: قُلْتُ لِأَنَسٍ: أَرَآكُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، رَآنَا فَلَمْ يَأْمُرْنَا، وَلَمْ يَنْهَنَا. (م,د)', 'അനസ്(റ): നബി(സ)യുടെ കാലത്ത് മഗ്രിബിനു മുമ്പുള്ള രണ്ട് റക്അത്ത് ഞാൻ നിസ്കരിച്ചിട്ടുണ്ട്. (അനസി(റ)ൽ നിന്നുദ്ധരിക്കുന്ന) റിപ്പോർട്ടർ ഇപ്രകാരം പറയുന്നു: ഞാൻ അനസ്(റ)വിനോട് ചോദിച്ചു: നിങ്ങളെ നബി(സ) കണ്ടിരുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: അതെ, ഞങ്ങളെ കണ്ടിട്ടുണ്ട്. എന്നിട്ട് നബി(സ) അതിനെക്കുറിച്ച് കൽപിക്കുകയോ വിരോധിക്കുകയോ ചെയ്തില്ല. (മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَبْدِ اللهِ بْنِ مُغَفَّلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ لِمَنْ شَاءَ". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): നബി(സ) പറഞ്ഞു: "ഉദ്ദേശിക്കുന്നവർക്ക് എല്ലാ രണ്ട് ബാങ്കുകൾക്കിടയിലും (ബാങ്കിനും ഇഖാമത്തിനും ഇടക്ക്) നിസ്കാരമുണ്ട്." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، وَقَدْ سُئِلَ عَنِ الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ، فَقَالَ: مَا رَأَيْتُ أَحَدًا عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهِمَا، وَرَخَّصَ فِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ. (د)', 'ഇബ്നു ഉമർ(റ): മഗ്രിബിനു മുമ്പുള്ള നിസ്കാരത്തെക്കുറിച്ച് അദ്ദേഹം ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ)യുടെ കാലത്ത് അത് ആരും നിസ്കരിക്കുന്നതായി ഞാൻ കണ്ടിട്ടില്ല. അസ്വറിനു ശേഷമുള്ള രണ്ട് റക്അത്തിൽ നബി(സ) ഇളവ് നൽകിയിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: حَفِظْتُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَشْرَ رَكَعَاتٍ، كَانَ يُصَلِّيهَا بِاللَّيْلِ وَالنَّهَارِ: رَكْعَتَيْنِ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا، وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ، وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ الْآخِرَةِ، وَحَدَّثَتْنِي حَفْصَةُ: أَنَّهُ كَانَ يُصَلِّي قَبْلَ الْفَجْرِ رَكْعَتَيْنِ. حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നു ഉമർ(റ): രാത്രിയിലും, പകലിലുമായി നബി(സ) നിസ്കരിക്കുന്ന പത്ത് റക്അത്തുകൾ തിരുമേനി(സ)യിൽ നിന്നും ഞാൻ മന:പാഠമാക്കി. ളുഹ്റിനു മുമ്പ് രണ്ട്, ശേഷം രണ്ട്, മഗ്രിബിന് ശേഷം രണ്ട്, ഇശാഇന് ശേഷം രണ്ട്. ഹഫ്സ(റ) എന്നോട് പറഞ്ഞു: നബി(സ) സുബ്ഹിക്കു മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ട്. ഹദീസ് ഹസനും സഹീമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنْ كَانَ الْمُؤَذِّنُ لَيُؤَذِّنُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَرَى أَنَّهَا الْإِقَامَةُ، مِنْ كَثْرَةِ مَنْ يَقُومُ فَيُصَلِّي الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ. (جه)', 'അനസുബ്നു മാലിക്(റ): മഗ്രിബിനു മുമ്പുള്ള രണ്ട് റക്അത്ത് സുന്നത്ത് നിസ്കരിക്കാനായി എഴുന്നേറ്റ് നിൽക്കുന്നവരുടെ ആധിക്യം കാരണം നബി(സ)യുടെ കാലത്ത് മുഅദ്ദിൻ ബാങ്കു വിളിക്കുമ്പോൾ അത് ഇഖാമത്താണോ എന്ന് തോന്നിപ്പോകുമായിരുന്നു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ مُخْتَارِ بْنِ فُلْفُلٍ قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ رَضِيَ اللهُ عَنْهُ عَنِ التَّطَوُّعِ بَعْدَ الْعَصْرِ، فَقَالَ: كَانَ عُمَرُ يَضْرِبُ الْأَيْدِي عَلَى صَلَاةٍ بَعْدَ الْعَصْرِ، وَكُنَّا نُصَلِّي عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ بَعْدَ غُرُوبِ الشَّمْسِ قَبْلَ صَلَاةِ الْمَغْرِبِ. فَقُلْتُ لَهُ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّاهُمَا؟ قَالَ: كَانَ يَرَانَا نُصَلِّيهِمَا، فَلَمْ يَأْمُرْنَا وَلَمْ يَنْهَنَا. (م)', 'മുഖ്താറുബിനു ഫുൽഫുൽ: ഞാൻ അനസി(റ)നോട് അസ്റിനു ശേഷമുള്ള സുന്നത്ത് നിസ്കാരത്തെക്കുറിച്ചു ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: ''ഉമർ(റ) അസ്റിനു ശേഷം സുന്നത്ത് നിസ്കരിക്കുന്നവരുടെ കയ്യിന് അടിക്കാറുണ്ടായിരുന്നു. ഞങ്ങളാകട്ടെ റസൂലി(സ)ന്റെ കാലത്ത് സൂര്യാസ്തമയശേഷം മഗ്രിബിനു മമ്പായി രണ്ടു റക്അത്തുകൾ നിസ്കരിച്ചിരുന്നു''. ഇതു പറഞ്ഞപ്പോൾ ഞാനദ്ദേഹത്തോടു ചോദിച്ചു. റസൂൽ(സ) ആ രണ്ടു റക്അത്തുകൾ നിസ്കരിച്ചിരുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ ആ രണ്ട് റക്അത്തുകൾ നിസ്കരിച്ചിരുന്നത് തിരുമേനി(സ) കണ്ടിരുന്നു. എന്നാൽ ഞങ്ങളോട് തിരുമേനി(സ) അക്കാര്യത്തിൽ കൽപ്പിക്കുകയോ വിലക്കുകയോ ചെയ്തിട്ടില്ല. (മു)', 'مُخْتَارِ بْنِ فُلْفُلٍ قَالَ', 'മുഖ്താറുബിനു ഫുൽഫുൽ', null, null, array['م']::text[], array['മു']::text[], null, null, 540, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى بَعْدَ الْمَغْرِبِ سِتَّ رَكَعَاتٍ، لَمْ يَتَكَلَّمْ فِيمَا بَيْنَهُنَّ بِسُوءٍ، عُدِلْنَ لَهُ بِعِبَادَةِ ثِنْتَيْ عَشْرَةَ سَنَةً". (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും മഗ്രിബ് നിസ്കാരാനന്തരം ആറ് റക്അത്ത് നിസ്കരിക്കുകയും, അതിനിടയിൽ അനാവശ്യ സംസാരങ്ങൾ ഒഴിവാക്കുകയും ചെയ്താൽ അതവന് പന്ത്രണ്ട് വർഷത്തെ ആരാധനക്ക് തുല്യമാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الْمَغْرِبَ، ثُمَّ يَرْجِعُ إِلَى بَيْتِي فَيُصَلِّي رَكْعَتَيْنِ. (جه)', 'ആഇശ(റ): നബി(സ) മഗ്രിബ് നിസ്കാരാനന്തരം എന്റെ വീട്ടിലേക്ക് മടങ്ങിവന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي بَيْتِهِ. حسن صحيح. (خ,ت)', 'ഇബ്നു ഉമർ(റ): ഞാൻ നബി(സ)യുടെ വീട്ടിൽ വെച്ച് അവിടത്തോടൊപ്പം മഗ്രിബിനുശേഷം രണ്ട് റക്അത്ത് നിസ്കരിച്ചിട്ടുണ്ട്. ഹദീസ് ഹസനും സഹീഹുമാണ്. (ബു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ مَحْمُودِ بْنِ لَبِيدٍ، عَنْ رَافِعِ بْنِ خَدِيجٍ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: أَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَنِي عَبْدِ الْأَشْهَلِ، فَصَلَّى بِنَا الْمَغْرِبَ فِي مَسْجِدِنَا، ثُمَّ قَالَ: "ارْكَعُوا هَاتَيْنِ الرَّكْعَتَيْنِ فِي بُيُوتِكُمْ". ز: اسناده ضعيف. (جه)', 'മഹ്മൂദുബ്നു ലബീദ്, റാഫിഉബ്നു ഖദീജ്(റ): ബനൂഅബ്ദുൽ അശ്ഹലിലായിരിക്കെ നബി(സ) ഞങ്ങളുടെ അടുത്തേക്കു വന്ന് ഞങ്ങളുടെ പള്ളിയിൽ ഞങ്ങൾക്ക് ഇമാമായി മഗ്രിബ് നിസ്കരിച്ചു. ശേഷം പറഞ്ഞു: "ഈ (ഇപ്പോഴുള്ള) രണ്ട് റക്അത്ത് (സുന്നത്ത്) നിങ്ങൾ നിങ്ങളുടെ വീട്ടിൽവെച്ച് നിർവ്വഹിക്കുക." ഇതിന്റെ പരമ്പയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ജ)', 'مَحْمُودِ بْنِ لَبِيدٍ، عَنْ رَافِعِ بْنِ خَدِيجٍ –', 'മഹ്മൂദുബ്നു ലബീദ്, റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ بَعْدَ صَلَاةِ الْمَغْرِبِ: {قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ {قُلْ هُوَ اللهُ أَحَدٌ}. (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): മഗ്രിബിന് ശേഷമുള്ള രണ്ട് റക്അത്ത് നിസ്കാരത്തിൽ നബി(സ) قل يا ايها الكافرون، قل هو الله أحد എന്നീ സൂറത്തുകൾ പാരായണം ചെയ്യുമായിരുന്നു. (തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَتَى مَسْجِدَ بَنِي عَبْدِ الْأَشْهَلِ فَصَلَّى فِيهِ الْمَغْرِبَ، فَلَمَّا قَضَوْا صَلَاتَهُمْ رَآهُمْ يُسَبِّحُونَ بَعْدَهَا، فَقَالَ: "هَذِهِ صَلَاةُ الْبُيُوتِ". (د,ت,جه)', 'കഅ്ബുബ്നുഉജ്റ(റ): ബനൂഅബ്ദിൽ അശ്ഹലിന്റെ പള്ളിയിൽ നബി(സ) മഗ്രിബ് നിസ്കരിച്ചു. നിസ്കാര ശേഷം ആളുകൾ സുന്നത്ത് നിസ്കരിക്കുന്നത് നബി(സ) കണ്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഈ നിസ്കാരം നിങ്ങൾ വീടുകളിൽ വെച്ചാണ് നിർവ്വഹിക്കേണ്ടത്." (ദ,തു,ജ)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്നുഉജ്റ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِ بَنِي عَبْدِ الْأَشْهَلِ، فَقَامَ نَاسٌ يَتَنَفَّلُونَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِهَذِهِ الصَّلَاةِ فِي الْبُيُوتِ". (د,ت,ن)', 'കഅ്ബുബ്നു ഉജ്റ(റ): ബനൂഅബ്ദിൽ അശ്ഹലിന്റെ പള്ളിയിൽ നബി(സ) നിസ്കരിച്ചു. ശേഷം ആളുകൾ സുന്നത്ത് നിസ്കരിക്കാനായി എഴുന്നേറ്റപ്പോൾ നബി(സ) പറഞ്ഞു: "ഈ നിസ്കാരം നിങ്ങൾ വീടുകളിൽ വെച്ച് നിർവ്വഹിക്കുക." (ദ,തു,ന)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്നു ഉജ്റ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُطِيلُ الْقِرَاءَةَ فِي الرَّكْعَتَيْنِ بَعْدَ الْمَغْرِبِ حَتَّى يَتَفَرَّقَ أَهْلُ الْمَسْجِدِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മഗ്രിബിനു ശേഷമുള്ള രണ്ട് റക്അത്തുകളിൽ പള്ളിയിലുള്ള ആളുകൾ പിരിയുന്നതുവരെ ഖുർആൻ പാരായണം ദീർഘിപ്പിക്കാറുണ്ടായിരുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ عِشْرِينَ رَكْعَةً بَنَى اللهُ لَهُ بَيْتًا فِي الْجَنَّةِ". [ز:في إسناده ضعيف متهم بالكذب] (جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഇശാ മഗ്രിബ് നിസ്കാരങ്ങൾക്കിടയിൽ ഇരുപത് റക്അത്ത് നിസ്കരിച്ചാൽ അല്ലാഹു അവന് സ്വർഗ്ഗത്തിൽ ഒരു ഭവനം നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്." (ഇതിന്റെ പരമ്പരയിൽ കള്ളം ആരോപിക്കപ്പെട്ട ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നു മാജ പറയുന്നു) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:في إسناده ضعيف متهم بالكذب', 'ഇതിന്റെ പരമ്പരയിൽ കള്ളം ആരോപിക്കപ്പെട്ട ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നു മാജ പറയുന്നു', 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: مَا صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ قَطُّ فَدَخَلَ عَلَيَّ إِلَّا صَلَّى أَرْبَعَ رَكَعَاتٍ، أَوْ سِتَّ رَكَعَاتٍ، وَلَقَدْ مُطِرْنَا مَرَّةً بِاللَّيْلِ فَطَرَحْنَا لَهُ نِطَعًا، فَكَأَنِّي أَنْظُرُ إِلَى ثُقْبٍ فِيهِ يَنْبُعُ الْمَاءُ مِنْهُ، وَمَا رَأَيْتُهُ مُتَّقِيًا الْأَرْضَ بِشَيْءٍ مِنْ ثِيَابِهِ قَطُّ. (د)', 'ആഇശ(റ): നബി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് അവർ ചോദിക്കപ്പെട്ടപ്പോൾ അവർ പറഞ്ഞു: നബി(സ) ഇശാ നിസ്കാരാനന്തരം എന്റെ അടുത്തേക്ക് വന്നാൽ നാലോ, ആറോ റക്അത്തുകൾ നിസ്കരിക്കാതിരിക്കാറില്ല. ഒരു ദിവസം രാത്രി മഴ പെയ്തു. നബി(സ)ക്ക് ഞങ്ങൾ ഒരു വിരിപ്പിട്ടു കൊടുത്തു. ആ വിരിപ്പിന് ഒരു ദ്വാരമുള്ളതും അതിലൂടെ വെള്ളം പുറത്ത് വരുന്നതും ഞാൻ ഇപ്പോഴും നോക്കിക്കാണുന്നതു പോലെയുണ്ട്. അല്ലാഹുവിന്റെ റസുലാകട്ടെ, തന്റെ വസ്ത്രം നിലത്താവുന്ന കാര്യത്തേക്കാൾ മറ്റൊന്നും സുക്ഷിക്കുന്നതായി ഞാൻ തിരുമേനി(സ)യെ കണ്ടിട്ടില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 542, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي قَبْلَ الظُّهْرِ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ، وَبَعْدَ الْمَغْرِبِ ثِنْتَيْنِ، وَبَعْدَ الْعِشَاءِ رَكْعَتَيْنِ، وَقَبْلَ الْفَجْرِ ثِنْتَيْنِ. حَسَنٌ صَحِيحٌ. (م,ت)', 'ആഇശ(റ): നബി(സ) ളുഹ്റിനു മുമ്പ് രണ്ട്, ശേഷം രണ്ട്, മഗ്രിബിനു ശേഷം രണ്ട്, ഇശാഇനു ശേഷം രണ്ട്, സുബ്ഹിക്ക് മുമ്പ് രണ്ട് എന്നിങ്ങനെ നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: احْتَجَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حُجَيْرَةً بِخَصَفَةٍ أَوْ حَصِيرٍ، فَخَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِيهَا، قَالَ: فَتَتَبَّعَ إِلَيْهِ رِجَالٌ، وَجَاءُوا يُصَلُّونَ بِصَلَاتِهِ، قَالَ: ثُمَّ جَاءُوا لَيْلَةً، فَحَضَرُوا وَأَبْطَأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْهُمْ، قَالَ: فَلَمْ يَخْرُجْ إِلَيْهِمْ، فَرَفَعُوا أَصْوَاتَهُمْ، وَحَصَبُوا الْبَابَ، فَخَرَجَ إِلَيْهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُغْضَبًا، فَقَالَ لَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا زَالَ بِكُمْ صَنِيعُكُمْ حَتَّى ظَنَنْتُ أَنَّهُ سَيُكْتَبُ عَلَيْكُمْ، فَعَلَيْكُمْ بِالصَّلَاةِ فِي بُيُوتِكُمْ، فَإِنَّ خَيْرَ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا الصَّلَاةَ الْمَكْتُوبَةَ". وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ حُجْرَةً فِي الْمَسْجِدِ مِنْ حَصِيرٍ. (ق,د,ت,ن)', 'സൈദുബ്നു സാബിത്(റ): നബി(സ) പായ കൊണ്ടോ ഓല കൊണ്ടോ ഒരു റൂമുണ്ടാക്കി നിസ്കാരത്തിനായി അതിലേക്കു പുറപ്പെട്ടു. അപ്പോൾ ജനങ്ങളും നബി(സ) നിസ്കരിക്കുന്നതിനെ തുടർന്ന് നിസ്കരിക്കാൻ വന്നു. പിന്നെ ജനങ്ങൾ രാത്രിയും വന്നു. എന്നാൽ നബി(സ) വന്നില്ല. ജനങ്ങൾ ശബ്ദമുയർത്തുകയും വാതിലിൽ മുട്ടുകയും ചെയ്തു. അപ്പോൾ നബി(സ) ദേഷ്യത്തോടെ പുറത്തേക്ക് വന്നു കൊണ്ട് പറഞ്ഞു: "നിങ്ങൾ ഈ പ്രവൃത്തി (ഈ നിസ്കാരം) തുടർന്നാൽ അത് നിർബന്ധമാക്കപ്പെടുമോ എന്നു ഞാൻ കരുതുന്നു, അതിനാൽ നിങ്ങൾ വീട്ടിൽ വെച്ച് നിസ്കരിക്കുക. ഒരാളുടെ ഫർള് ഒഴികെയുള്ള നിസ്കാരങ്ങളിൽ അവന് ഉത്തമമായത് അവന്റെ വീട്ടിൽ വെച്ചുള്ള നിസ്കാരമാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: ''നബി(സ) പള്ളിയിൽ പായ കൊണ്ടുള്ള ഒരു റൂം ഉണ്ടാക്കി'' എന്നാണ്. (ബു,മു,ദ,തു,ന)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=21 and h.hadith_no=104), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ حُجْرَةً فِي الْمَسْجِدِ مِنْ حَصِيرٍ. (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനിൽ: ''നബി(സ) പള്ളിയിൽ പായ കൊണ്ടുള്ള ഒരു റൂം ഉണ്ടാക്കി'' എന്നാണ്. (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جِئْتُ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي الْبَيْتِ، وَالْبَابُ عَلَيْهِ مُغْلَقٌ، فَمَشَى حَتَّى فَتَحَ لِي، ثُمَّ رَجَعَ إِلَى مَكَانِهِ. وَوَصَفَتِ الْبَابَ فِي الْقِبْلَةِ. حَسَنٌ غَرِيبٌ. (د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) വീട്ടിൽ വെച്ച് നിസ്കരിച്ചു കൊണ്ടിരിക്കെ ഞാൻ അങ്ങോട്ടു കടന്നുചെന്നു. (വീടിന്റെ) വാതിൽ അടച്ചിട്ടിട്ടുണ്ടായിരുന്നു. അപ്പോൾ നബി(സ) നടന്നു വന്ന് എനിക്ക് വാതിൽ തുറന്നു തന്നു. ശേഷം തിരുമേനി(സ) തന്റെ സ്ഥലത്തേക്ക് തന്നെ മടങ്ങിപ്പോയി. വാതിൽ ഖിബ്ലയുടെ ഭാഗത്തായിരുന്നു എന്ന് ആഇശ(റ) വിശദീകരിച്ചു. ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു. (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=21 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
